-- 00273 — Constats-types PSSI-ES personnalisés (couverture complète, remplace le générique 00271).
-- Pour chaque contrôle : constat factuel + risques + recommandations rédigés à partir de
-- l'exigence réelle et de son équivalent ISO 27001. Variante « major » pour les contrôles
-- critiques (risk_level >= 4). Les lignes génériques de 00271 sont d'abord supprimées.
-- La garde NOT EXISTS préserve les starters rédigés 00270 (ne double pas leurs classifications).

-- (0) Retrait des constats-types génériques produits par 00271.
delete from public.finding_templates ft
using public.controls c
where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'minor_nc'
  and ft.description like 'Non-conformité à l''exigence %'
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000017');

-- (1) Constats-types personnalisés — NC mineure (tous les contrôles).
insert into public.finding_templates (scope, control_id, classification, description, risks, recommendations)
select 'platform', c.id, 'minor_nc', t.descr, t.risks, t.recos
from (values
  ('REG 1-1', 'Les membres du Comité de sécurité exerçant comme AQSSI n''ont pas suivi la sensibilisation/formation préalable à la sécurité des SI requise pour leurs missions.', ARRAY['Pilotage de la sécurité assuré par des responsables insuffisamment outillés.','Décisions de sécurité inadaptées faute de compétences.'], ARRAY['Faire suivre aux AQSSI une formation initiale avant prise de fonction.','Prévoir une remise à niveau périodique tenant compte de l''évolution des menaces.']),
  ('REG 1-2', 'La sensibilisation et la formation ne sont pas confiées à des organismes aux compétences avérées (ADIE, STCC-SSI, ARTP ou équivalent) ou leur contenu ne tient pas compte de l''évolution des menaces.', ARRAY['Formations de qualité insuffisante ou obsolètes.','Écart entre les compétences acquises et les menaces actuelles.'], ARRAY['Recourir à des organismes reconnus pour les formations en sécurité des SI.','Actualiser les contenus selon les menaces et attaques récentes.']),
  ('REG 1-3', 'Les ASSI ne sont pas sensibilisés en permanence à leurs responsabilités ni formés au même titre que les AQSSI.', ARRAY['Gestion des moyens de sécurité sur site mal maîtrisée.','Erreurs d''exploitation faute de formation à jour.'], ARRAY['Établir un plan de formation continue des ASSI.','Tracer les sessions et vérifier l''acquisition des compétences.']),
  ('REG 1-4', 'Aucune note d''organisation proposée par le RSSI et validée par l''autorité de l''entité ne fixe la répartition des responsabilités en matière de sécurité, ou elle est obsolète.', ARRAY['Responsabilités de sécurité floues ou non assumées.','Absence de mandat formel du RSSI.'], ARRAY['Rédiger une note d''organisation proposée par le RSSI.','La faire valider par l''autorité de l''entité et la diffuser.']),
  ('REG 1-5', 'Les actions de mise en place de la PSSI-ES ne sont pas planifiées par le RSSI : aucun plan avec échéances, responsables et jalons n''est établi.', ARRAY['Mise en œuvre de la PSSI-ES retardée ou incohérente.','Absence de visibilité de la direction sur l''avancement.'], ARRAY['Élaborer un plan d''action de mise en œuvre de la PSSI-ES.','Suivre l''avancement par des revues périodiques.']),
  ('REG 1-6', 'Les documents validés par le Chef de département ne sont pas formalisés et tenus à jour par le RSSI : versions obsolètes ou absence de gestion documentaire.', ARRAY['Application de procédures périmées.','Impossibilité de prouver la validation des documents.'], ARRAY['Mettre en place une gestion documentaire avec versions et dates de validation.','Revoir les documents à fréquence définie.']),
  ('REG 2-1', 'Les agents recrutés ne sont pas informés au préalable, lors de l''embauche, de leur rôle en matière de sécurité de l''information ni de leurs responsabilités dans l''application de la politique de sécurité de l''organisme.', ARRAY['Agents ignorant leurs obligations SSI et commettant des erreurs de manipulation de l''information.','Impossibilité d''opposer à un agent des règles dont il n''a pas été informé.'], ARRAY['Intégrer une session d''information SSI obligatoire au processus d''accueil de tout nouvel agent.','Insérer les responsabilités SSI dans les fiches de poste et contrats, et conserver la preuve de remise.','Remettre la politique de sécurité à chaque agent contre accusé de réception.']),
  ('REG 2-2', 'Les agents ne s''engagent pas formellement, par un document signé, à adopter un comportement responsable ne présentant aucun risque pour la sécurité de l''information.', ARRAY['Comportements à risque (partage de mots de passe, usage abusif des ressources) sans base d''engagement.','Difficulté à établir la responsabilité individuelle après un incident.'], ARRAY['Faire signer à chaque agent une charte d''utilisation des systèmes d''information.','Renouveler l''engagement lors des évolutions de la politique de sécurité ou des changements de poste.','Archiver les chartes signées dans le dossier du personnel.']),
  ('REG 2-3', 'Les agents et prestataires ayant accès à l''information sensible et aux systèmes d''information ne font pas l''objet d''enquêtes de sécurité et de moralité préalables, d''une habilitation ni de la signature d''une charte de confidentialité et de non-divulgation.', ARRAY['Accès d''une personne non vérifiée à des informations sensibles.','Absence d''engagement opposable en cas de divulgation par un agent ou un prestataire.','Exposition accrue à la menace interne.'], ARRAY['Mettre en place une procédure d''enquête et d''habilitation préalable à tout accès à l''information sensible.','Faire signer une charte de confidentialité et de non-divulgation aux agents et prestataires.','Tenir un registre des habilitations accordées, avec dates de revue.']),
  ('REG 2-4', 'Les agents ayant accès à l''information sensible ne sont pas informés de leurs responsabilités en matière de sécurité ni des sanctions encourues en cas de violation de la politique de sécurité.', ARRAY['Absence d''effet dissuasif face aux violations de la politique de sécurité.','Sanctions disciplinaires ou pénales contestables faute d''information préalable.'], ARRAY['Mentionner explicitement les sanctions applicables (Code pénal, statut général des fonctionnaires) dans la charte et le règlement intérieur.','Informer les agents concernés lors de l''habilitation et en conserver la preuve.','Rappeler périodiquement les sanctions dans les actions de sensibilisation.']),
  ('REG 2-5', 'Aucune obligation ni circuit de signalement sans délai au service compétent n''est défini ou connu des utilisateurs pour les événements susceptibles de dénoter un incident de sécurité informatique.', ARRAY['Incidents constatés par les utilisateurs mais jamais remontés.','Détection tardive et aggravation de l''impact d''une compromission.'], ARRAY['Définir et diffuser un canal unique de signalement (adresse, numéro, formulaire) vers le service compétent.','Inscrire l''obligation de signalement sans délai dans la charte des utilisateurs.','Rappeler la procédure lors des sessions de sensibilisation.']),
  ('REG 2-6', 'Le traitement des données à caractère personnel n''est pas conforme à la loi 2008-12 du 25 janvier 2008 : absence de déclaration ou d''autorisation auprès de la CDP et de mesures de protection documentées.', ARRAY['Sanctions administratives et pénales prévues par la loi 2008-12.','Fuite ou usage détourné de données personnelles portant atteinte aux personnes concernées.','Atteinte à l''image de l''organisme.'], ARRAY['Recenser les traitements de données personnelles et accomplir les formalités auprès de la CDP.','Définir les mesures de sécurité, durées de conservation et droits des personnes concernées.','Désigner un correspondant à la protection des données.']),
  ('REG 3-1', 'Les mouvements de personnel (arrivée, mutation, départ, fin de contrat) ne déclenchent pas de processus systématique de révocation des comptes et droits d''accès, de contrôle d''accès aux locaux et de restitution des équipements mobiles.', ARRAY['Comptes actifs d''agents partis, exploitables à des fins malveillantes.','Cumul de droits injustifiés après mutation, contraire au besoin d''en connaître.','Équipements et badges non restitués.'], ARRAY['Formaliser une procédure arrivée/mutation/départ associant RH, DSI et sécurité physique.','Révoquer ou adapter comptes, droits et accès aux locaux dès la date effective du mouvement.','Contrôler la restitution des équipements et réaliser une revue périodique des comptes.']),
  ('REG 4-1', 'Aucun programme de sensibilisation et de formation à la sécurité des systèmes d''information n''est élaboré, revu ni mis à jour régulièrement.', ARRAY['Utilisateurs vulnérables à l''hameçonnage et à l''ingénierie sociale.','Erreurs humaines à l''origine d''incidents évitables.'], ARRAY['Élaborer un programme annuel de sensibilisation et de formation SSI approuvé par la direction.','Prévoir sa revue et sa mise à jour au moins annuelles.','Suivre la participation et mesurer l''efficacité (taux de présence, tests).']),
  ('REG 4-2', 'Le contenu des actions de sensibilisation et de formation n''est pas aligné sur la politique de sécurité de l''organisme et n''en relaie pas les règles.', ARRAY['Messages de sensibilisation contradictoires avec les règles applicables.','Règles de la politique de sécurité mal connues et non appliquées.'], ARRAY['Dériver les thèmes de formation des règles de la politique de sécurité en vigueur.','Faire valider le programme par le responsable SSI.','Actualiser les supports à chaque évolution de la politique.']),
  ('REG 4-3', 'Le programme de sensibilisation est identique pour tous et ne tient pas compte des niveaux de responsabilité (direction, AQSSI, ASSI, utilisateurs finaux).', ARRAY['Dirigeants et administrateurs insuffisamment formés à leurs responsabilités spécifiques.','Contenu inadapté, peu suivi par les utilisateurs.'], ARRAY['Définir des parcours par profil : direction, AQSSI/ASSI, administrateurs, utilisateurs finaux.','Adapter le contenu et la fréquence à chaque profil.','Cartographier les rôles à former et suivre la couverture par profil.']),
  ('REG 4-4', 'Le programme de sensibilisation n''est pas mis à jour pour intégrer les nouveaux agents ni les enseignements tirés des incidents de sécurité survenus.', ARRAY['Nouveaux agents jamais formés.','Répétition d''incidents dont les causes n''ont pas été traitées par la sensibilisation.'], ARRAY['Prévoir une formation d''accueil systématique des nouveaux agents.','Alimenter le programme avec les retours d''expérience issus du registre des incidents.','Planifier une révision annuelle documentée du programme.']),
  ('REG 4-5', 'Le programme de sensibilisation ne fait pas apparaître l''engagement de la direction sur la sécurité des systèmes d''information.', ARRAY['Perception de la SSI comme secondaire par les agents.','Faible adhésion et ressources insuffisantes allouées au programme.'], ARRAY['Faire introduire le programme par un message signé de la direction générale.','Impliquer visiblement la direction dans les sessions de sensibilisation.','Associer la direction au suivi des indicateurs du programme.']),
  ('REG 4-6', 'Aucun programme de formation continue ni de veille technologique n''est mis en place pour les agents chargés de veiller à l''application de la politique de sécurité.', ARRAY['Responsables SSI ignorant les menaces et vulnérabilités récentes.','Mesures de protection obsolètes face aux nouvelles attaques.'], ARRAY['Établir un plan de formation continue annuel pour les AQSSI, ASSI et équipes sécurité.','Organiser une veille formalisée (bulletins CERT, ADIE, éditeurs) avec diffusion interne.','Conserver les attestations de formation.']),
  ('REG 5-1', 'Les exigences de sécurité (contrôle d''accès, confidentialité, disponibilité, intégrité, journalisation) ne sont pas intégrées dès l''entame des projets d''acquisition de nouveaux systèmes.', ARRAY['Acquisition de systèmes ne répondant pas aux exigences de sécurité.','Coûts de mise en conformité a posteriori.'], ARRAY['Intégrer une grille d''exigences de sécurité dans tous les cahiers des charges d''acquisition.','Valider la sécurité avant la recette.']),
  ('REG 5-2', 'Le développement logiciel n''est pas sécurisé : les locaux de développement ne sont pas protégés et les bonnes pratiques de sécurité du langage et du contrôle de versions ne sont pas appliquées.', ARRAY['Vulnérabilités introduites dans le code livré.','Vol ou altération du code source.'], ARRAY['Sécuriser l''environnement de développement physiquement et logiquement.','Appliquer des guides de codage sécurisé et un contrôle de versions rigoureux.']),
  ('REG 5-3', 'Les normes et standards de développement sécurisé (ISO, IEC) ne sont pas appliqués : aucun référentiel de développement sécurisé n''est adopté.', ARRAY['Qualité de sécurité variable selon les développeurs.','Vulnérabilités applicatives courantes non évitées.'], ARRAY['Adopter un référentiel de développement sécurisé aligné sur les normes ISO/IEC.','Former les développeurs et contrôler le respect par revue de code.']),
  ('REG 5-4', 'En cas d''externalisation du développement, le maître d''œuvre n''est pas contractuellement tenu de respecter les exigences de sécurité ni d''encadrer les licences, la qualité et les tests.', ARRAY['Livraison de logiciels non sécurisés ou mal licenciés.','Dépendance au prestataire sans garantie sur le code.'], ARRAY['Inclure dans les contrats les exigences de sécurité, de licences et de recette.','Auditer les livrables avant mise en production.']),
  ('REG 6-1', 'L''inventaire des actifs existe mais est incomplet ou obsolète : il ne couvre pas tous les actifs et n''est pas mis à jour régulièrement.', ARRAY['Actifs non protégés car non recensés.','Cartographie des risques fondée sur des données inexactes.'], ARRAY['Compléter l''inventaire et le rapprocher des constats physiques.','Définir un processus de mise à jour lors de chaque acquisition ou retrait.']),
  ('REG 6-2', 'Les actifs ne sont pas tous affectés à un responsable désigné chargé de leur classification, protection et contrôle d''accès.', ARRAY['Absence de responsable en cas d''incident sur un actif.','Droits d''accès non revus faute de propriétaire.'], ARRAY['Désigner un propriétaire pour chaque actif de l''inventaire.','Formaliser ses responsabilités (classification, protection, accès).']),
  ('REG 6-3', 'Les règles d''utilisation correcte de l''information, des actifs associés et des moyens de traitement ne sont pas documentées ou pas diffusées, ni appliquées de façon vérifiable.', ARRAY['Usages abusifs ou à risque des équipements et de l''information.','Impossibilité de sanctionner un usage non conforme.'], ARRAY['Rédiger et diffuser une charte d''utilisation des actifs.','Faire signer la charte par les utilisateurs et en contrôler l''application.']),
  ('REG 6-4', 'La restitution des actifs en fin de contrat ou de mission n''est pas systématique : aucun contrôle ne vérifie que la totalité des actifs est rendue.', ARRAY['Équipements et données conservés par d''anciens agents ou prestataires.','Accès résiduels exploitables après le départ.'], ARRAY['Intégrer la restitution contrôlée des actifs dans la procédure de départ.','Faire signer un bordereau de restitution et révoquer les accès associés.']),
  ('REG 6-5', 'Les informations ne sont pas classifiées selon leur sensibilité conformément à l''Instruction 0303/PR (TRÈS SECRET, SECRET, CONFIDENTIEL), ou la classification n''est pas appliquée de façon cohérente.', ARRAY['Informations sensibles traitées sans protection adaptée.','Divulgation d''informations classifiées par défaut de marquage.'], ARRAY['Définir et appliquer un schéma de classification aligné sur l''Instruction 0303/PR.','Marquer les informations et former les agents aux règles de traitement.']),
  ('REG 6-6', 'Les supports amovibles contenant des informations ne font l''objet d''aucune protection systématique (chiffrement, contrôle d''usage, stockage sécurisé).', ARRAY['Perte ou vol d''un support entraînant la divulgation de données.','Introduction de codes malveillants via des supports non maîtrisés.'], ARRAY['Chiffrer les supports amovibles contenant des données sensibles.','Encadrer et journaliser l''usage des supports, et désactiver les ports non nécessaires.']),
  ('REG 6-7', 'La mise au rebut des matériels ne comporte pas d''effacement sécurisé systématique conforme à l''Instruction 0303/PR, ni de preuve de cet effacement.', ARRAY['Récupération de données sur des matériels cédés ou jetés.','Divulgation d''informations classifiées via le rebut.'], ARRAY['Imposer un effacement sécurisé ou une destruction avant toute mise au rebut.','Établir un certificat d''effacement pour chaque matériel.']),
  ('REG 7-1', 'Une politique de sécurité fournisseurs existe mais elle est incomplète ou non validée : elle ne couvre pas tous les types de fournisseurs (logistique, finance, informatique) et n''est pas systématiquement imposée aux prestataires.', ARRAY['Niveaux d''exigence de sécurité hétérogènes selon les fournisseurs.','Prestataires non couverts par la politique et accédant à des données sensibles sans encadrement.'], ARRAY['Compléter et faire valider la politique pour tous les types de fournisseurs.','Annexer la politique aux contrats et en exiger l''acceptation écrite.','Réviser la politique à fréquence définie.']),
  ('REG 7-2', 'Le suivi de la conformité des fournisseurs aux exigences de sécurité est ponctuel et non formalisé : il ne couvre pas tous les fournisseurs et n''est pas tracé.', ARRAY['Dérives de conformité des fournisseurs détectées tardivement.','Impossibilité de démontrer le respect des exigences contractuelles.'], ARRAY['Formaliser une procédure de suivi avec périodicité et indicateurs par fournisseur.','Conserver les preuves de revue (rapports de service, attestations).']),
  ('REG 7-3', 'La sensibilisation du personnel en contact avec les fournisseurs sur les règles de sécurité et les niveaux d''accès est partielle ou ponctuelle, sans périodicité ni suivi des participants.', ARRAY['Agents accordant des accès ou partageant des informations aux fournisseurs hors règles.','Pratiques hétérogènes selon les services.'], ARRAY['Planifier des sessions régulières à destination des agents en relation avec les fournisseurs.','Tracer les participations et évaluer les acquis.']),
  ('REG 7-4', 'Une charte de sécurité fournisseur existe mais n''est pas signée par tous les fournisseurs concernés, ou les signatures ne sont pas conservées.', ARRAY['Engagements de sécurité inopposables pour certains fournisseurs.','Fournisseurs ignorant les clauses applicables.'], ARRAY['Recenser les fournisseurs n''ayant pas signé et régulariser.','Archiver les chartes signées et les renouveler lors des révisions.']),
  ('REG 7-5', 'Les exigences légales (protection des données, droits d''auteur, propriété intellectuelle) sont rappelées de façon incomplète aux fournisseurs, sans vérification de leur respect.', ARRAY['Traitements de données personnelles par des fournisseurs sans garanties adaptées.','Usage de logiciels ou contenus sans droits appropriés.'], ARRAY['Inclure dans les contrats un rappel des obligations (loi 2008-12, propriété intellectuelle).','Vérifier périodiquement le respect de ces obligations.']),
  ('REG 7-6', 'Un interlocuteur sécurité pour les fournisseurs est identifié de manière informelle, sans désignation ni périmètre écrits, et reste inconnu de certains fournisseurs.', ARRAY['Remontée tardive des incidents par les fournisseurs.','Échanges de sécurité dispersés entre plusieurs services.'], ARRAY['Désigner formellement le point focal et communiquer ses coordonnées aux fournisseurs.','Définir son périmètre et prévoir un suppléant.']),
  ('REG 7-7', 'Les sous-traitants des fournisseurs ne sont que partiellement identifiés et pris en compte : la liste des intervenants n''est pas tenue à jour.', ARRAY['Intervenants tiers non connus ayant accès aux données de l''organisme.','Exigences de sécurité non répercutées sur certains sous-traitants.'], ARRAY['Exiger des fournisseurs la liste à jour de leurs sous-traitants.','Prévoir l''autorisation préalable de tout nouveau sous-traitant.']),
  ('REG 7-8', 'Les clauses contractuelles ne couvrent que partiellement la chaîne d''approvisionnement informatique : la conformité aux normes de sécurité des produits ou la preuve des exigences satisfaites n''est pas systématiquement exigée.', ARRAY['Acquisition de produits dont le niveau de sécurité n''est pas démontré.','Difficulté à faire valoir des garanties sur la sécurité des produits.'], ARRAY['Compléter les contrats par des clauses de conformité aux normes de sécurité des produits.','Exiger les preuves de conformité (certifications, rapports) à la livraison.']),
  ('REG 7-9', 'Les audits des prestations des fournisseurs sont réalisés de manière irrégulière, sans procédure ni plan, et ne couvrent pas la qualité de service.', ARRAY['Dérives des prestations découvertes tardivement.','Faiblesses de sécurité des fournisseurs non identifiées.'], ARRAY['Établir un plan annuel d''audit des fournisseurs selon leur criticité.','Formaliser la procédure, les critères et le suivi des écarts.']),
  ('REG 8-1', 'Les zones sécurisées (centres de données, salles serveurs, salles de commutation, stockage, équipements réseau) sont identifiées de façon partielle : certaines salles techniques ne sont ni listées ni signalées comme zones sécurisées.', ARRAY['Les locaux techniques non classés ne bénéficient d''aucune mesure d''accès renforcée.','Des équipements critiques peuvent être hébergés dans des locaux ordinaires sans que cela soit détecté.'], ARRAY['Établir et tenir à jour la liste formelle des zones sécurisées, validée par la direction.','Signaler physiquement chaque zone et la rattacher à un responsable désigné.']),
  ('REG 8-2', 'L''accès aux zones sécurisées est contrôlé de façon incomplète : l''autorisation écrite ou le badge n''est pas exigé à tous les points d''accès et la délivrance n''est pas toujours validée par le responsable désigné.', ARRAY['Des accès non autorisés ou non tracés restent possibles en cas d''incident.','Des badges délivrés sans validation formelle accroissent le nombre de personnes habilitées à tort.'], ARRAY['Généraliser le badge nominatif ou l''autorisation écrite à tous les points d''accès des zones sécurisées.','Faire valider chaque délivrance de badge par le responsable désigné et tenir la liste des titulaires.']),
  ('REG 8-3', 'Le registre d''accès aux zones sécurisées existe mais est incomplet : certaines rubriques (but, signature, heure de sortie) ne sont pas renseignées ou le registre n''est pas présent à l''entrée de chaque zone.', ARRAY['Impossibilité de reconstituer précisément qui était présent lors d''un incident.','Preuves d''accès non exploitables lors d''une enquête ou d''un audit.'], ARRAY['Standardiser le registre avec identité, but, signature, heures d''entrée et de sortie obligatoires.','Placer un registre à l''entrée de chaque zone et en contrôler le renseignement périodiquement.']),
  ('REG 8-4', 'La présence d''un agent de sécurité à l''entrée des sites sensibles est partielle : certains sites ou plages horaires ne sont pas couverts, ou l''agent n''assure pas l''ensemble des missions (registre, contrôle des bagages, alarmes).', ARRAY['Des personnes non autorisées peuvent entrer pendant les plages sans surveillance.','Des objets non contrôlés (bagages) peuvent être introduits sur le site.'], ARRAY['Couvrir tous les sites sensibles et toutes les plages d''ouverture par un agent de sécurité.','Formaliser la consigne de poste : interdiction d''accès, registre, contrôle des bagages, alarmes et appels d''urgence.']),
  ('REG 8-5', 'La fermeture des zones sécurisées hors heures de service est inégale : des fenêtres, issues de secours ou conduits (climatisation, élévateurs) ne sont pas systématiquement verrouillés ou munis de grilles métalliques.', ARRAY['Intrusion nocturne possible par une ouverture non verrouillée ou un conduit non protégé.','Vol de matériel hors des heures de présence du personnel.'], ARRAY['Verrouiller toutes les portes, fenêtres et issues de secours à la fermeture, avec une checklist de fermeture signée.','Équiper tous les conduits de grilles métalliques et vérifier leur état périodiquement.']),
  ('REG 8-6', 'La révocation des droits d''accès physiques lors des départs, mutations, suspensions ou longs congés n''est pas systématique ni immédiate ; des badges de personnes parties restent actifs un certain temps.', ARRAY['Un ancien agent peut pénétrer dans une zone sécurisée après son départ.','Des droits d''accès obsolètes s''accumulent et élargissent la surface d''exposition.'], ARRAY['Lier la désactivation des badges au processus RH (départ, mutation, suspension, congé long) avec délai maximal défini.','Réaliser une revue périodique des badges actifs rapprochée de la liste du personnel.']),
  ('REG 8-7', 'Les enregistrements d''accès sont sauvegardés de façon irrégulière et leur durée de conservation n''est pas définie ou pas respectée.', ARRAY['Des enregistrements disparaissent avant d''être exploitables lors d''une enquête.','Perte de preuves en cas de litige ou d''incident de sécurité.'], ARRAY['Définir une durée de conservation des enregistrements d''accès et la formaliser dans une procédure.','Planifier des sauvegardes régulières et tester leur restauration.']),
  ('REG 8-8', 'Le choix des techniques et équipements de sécurité physique n''est que partiellement justifié : l''évaluation de risque physique ou l''analyse coûts-avantages est ancienne ou incomplète.', ARRAY['Des équipements inadaptés ou surdimensionnés sont retenus sans justification.','Des risques physiques majeurs restent sans contre-mesure proportionnée.'], ARRAY['Mettre à jour l''évaluation du risque physique de chaque site.','Documenter l''analyse coûts-avantages de chaque contre-mesure retenue.']),
  ('REG 9-1', 'L''accès des visiteurs est partiellement encadré : la carte visiteur est délivrée sans authentification systématique de l''identité ou le registre (but, heures d''entrée et de sortie) est incomplet.', ARRAY['Un visiteur non identifié peut circuler dans les locaux sans traçabilité.','Un badge visiteur non restitué reste utilisable.'], ARRAY['Vérifier systématiquement une pièce d''identité avant de remettre la carte visiteur.','Compléter le registre des visites (identité, but, heures) et contrôler la restitution des cartes.']),
  ('REG 9-2', 'Des visites ont lieu en dehors des heures de service ou de pause sans dérogation formelle, la règle étant connue mais non appliquée de façon constante.', ARRAY['Des visiteurs accèdent aux locaux lorsque la surveillance est réduite.','Absence de personnel pour accompagner et contrôler les visiteurs.'], ARRAY['Interdire formellement les visites hors heures de service et diffuser la règle à l''accueil et aux agents.','Exiger une dérogation écrite et validée pour toute exception, et la consigner.']),
  ('REG 9-3', 'Le port d''un moyen d''identification visible n''est pas respecté par tous les agents, et les visiteurs non accompagnés ou sans badge ne sont pas systématiquement signalés au personnel de sécurité.', ARRAY['Une personne non autorisée peut circuler sans être repérée.','Les agents ne réagissent pas face à un visiteur non accompagné.'], ARRAY['Rendre obligatoire le port visible du badge pour tous les agents et le faire respecter par la hiérarchie.','Sensibiliser le personnel à la consigne d''alerter la sécurité devant toute personne non identifiée.']),
  ('REG 9-4', 'L''accès à la salle des serveurs n''est pas strictement limité aux personnes autorisées : la liste des habilités n''est pas à jour et des personnes non listées y accèdent ponctuellement.', ARRAY['Des personnes sans besoin légitime peuvent manipuler les serveurs.','Erreur humaine ou malveillance sur des équipements critiques.'], ARRAY['Établir et tenir à jour la liste nominative des personnes autorisées à entrer en salle serveurs.','Revoir cette liste périodiquement et retirer les accès sans justification.']),
  ('REG 10-1', 'Certains équipements-clés sont installés dans des emplacements accessibles au public ou sans protection contre le rayonnement électromagnétique (absence de cage de Faraday).', ARRAY['Interception de signaux compromettants émis par les équipements.','Accès de tiers à des équipements stratégiques depuis des espaces ouverts.'], ARRAY['Déplacer les équipements-clés vers des locaux non accessibles au public.','Évaluer et déployer des protections contre les fuites électromagnétiques (cages de Faraday) pour les équipements traitant des données sensibles.']),
  ('REG 10-2', 'Les répertoires et annuaires téléphoniques internes localisant les moyens de traitement de l''information sensible sont accessibles sans autorisation, y compris au personnel non concerné ou aux visiteurs.', ARRAY['Un tiers peut identifier l''emplacement des salles et équipements sensibles.','Facilitation de la préparation d''une intrusion ou d''une ingénierie sociale.'], ARRAY['Restreindre l''accès aux annuaires et répertoires internes aux seules personnes autorisées.','Retirer des annuaires diffusés les mentions de localisation des moyens de traitement sensibles.']),
  ('REG 10-3', 'Les bâtiments abritant des activités de traitement de l''information portent des indications visibles (signalétique, enseignes) révélant la présence de salles informatiques ou de centres de données.', ARRAY['Les locaux sensibles sont facilement repérés par des personnes malveillantes.','Exposition accrue aux intrusions ciblées ou au vandalisme.'], ARRAY['Retirer ou neutraliser la signalétique externe indiquant la présence d''activités de traitement de l''information.','Limiter la signalisation interne aux seules personnes concernées.']),
  ('REG 11-1', 'Le personnel n''est que partiellement informé de l''existence des zones sécurisées et du principe du besoin d''en connaître ; des agents accèdent à ces zones sans justification métier.', ARRAY['Accès de personnes sans besoin légitime aux zones sensibles.','Méconnaissance des règles conduisant à des pratiques à risque.'], ARRAY['Informer tout le personnel des zones sécurisées et des règles d''accès lors de l''accueil et par rappels réguliers.','Limiter les autorisations au strict besoin d''en connaître et les justifier par écrit.']),
  ('REG 11-2', 'Le travail sans surveillance dans les zones sécurisées n''est pas systématiquement évité : des intervenants ou agents y travaillent seuls sans accompagnement ni supervision, notamment en dehors des heures normales.', ARRAY['Actes malveillants ou erreurs non détectés en l''absence de témoin.','Absence de secours en cas d''accident ou de sinistre.'], ARRAY['Exiger la présence ou la supervision d''une seconde personne pour tout travail en zone sécurisée.','Soumettre les interventions hors horaires à autorisation préalable et suivi.']),
  ('REG 11-3', 'Les zones sécurisées inoccupées ne sont pas toujours verrouillées et leur contrôle périodique n''est pas formalisé ni tracé.', ARRAY['Une zone laissée ouverte peut être investie sans être détectée.','Les anomalies physiques ne sont pas constatées rapidement.'], ARRAY['Verrouiller toute zone sécurisée dès qu''elle est inoccupée.','Planifier des rondes de contrôle périodiques et les consigner.']),
  ('REG 11-4', 'L''interdiction des équipements photo, vidéo et audio en zones sécurisées est partiellement appliquée : la règle n''est pas affichée à toutes les entrées et les smartphones ne sont pas contrôlés, sans procédure d''autorisation formalisée.', ARRAY['Photographies ou enregistrements de l''infrastructure sensible par des visiteurs ou des agents.','Fuite d''informations sur l''agencement et les équipements.'], ARRAY['Afficher l''interdiction à l''entrée des zones sécurisées et la rappeler aux visiteurs.','Formaliser une procédure d''autorisation écrite pour toute exception.']),
  ('REG 12-1', 'La zone d''approvisionnement des matières entrantes est désignée mais son accès n''est pas strictement restreint au personnel de livraison ; elle n''est pas toujours séparée des zones de travail.', ARRAY['Des livreurs peuvent circuler vers les zones internes sans contrôle.','Des matières entrantes peuvent être détournées ou altérées.'], ARRAY['Délimiter physiquement la zone d''approvisionnement et limiter son accès au personnel de livraison.','Séparer cette zone des locaux de travail et des zones sécurisées.']),
  ('REG 12-2', 'L''inspection des matières entrantes est irrégulière : certaines livraisons quittent la zone de livraison sans contrôle de substances dangereuses ou avec des moyens de détection inadaptés.', ARRAY['Introduction de substances dangereuses sur le site.','Incident (incendie, contamination) causé par un colis non contrôlé.'], ARRAY['Soumettre toute matière entrante à une inspection avant sortie de la zone de livraison.','Doter la zone d''équipements de contrôle adaptés et en tracer l''usage.']),
  ('REG 12-3', 'Les matières entrantes sont enregistrées avec retard ou de façon incomplète, sans application systématique de la procédure d''enregistrement des actifs dès l''arrivée.', ARRAY['Des matériels livrés échappent temporairement à l''inventaire.','Écarts entre commandes, livraisons et actifs enregistrés non détectés.'], ARRAY['Enregistrer chaque matière entrante dès son arrivée selon la procédure d''enregistrement des actifs.','Rapprocher systématiquement bon de livraison, commande et enregistrement.']),
  ('REG 12-4', 'La comptabilité matière n''est pas intégralement assurée par les directions chargées des équipements : certaines entités ne tiennent pas de comptabilité à jour ou la confient à d''autres services.', ARRAY['Écarts entre équipements détenus et équipements comptabilisés.','Responsabilité floue pour les pertes ou vols de matériels.'], ARRAY['Confier formellement la comptabilité matière à la direction chargée des équipements dans chaque entité.','Réaliser des rapprochements périodiques avec l''inventaire physique.']),
  ('REG 13-1', 'Les installations sensibles disposent de systèmes d''alarme dont le contrôle périodique n''est pas réalisé à la fréquence requise ou n''est pas tracé.', ARRAY['Une alarme défaillante n''est pas détectée avant un sinistre ou une intrusion.','Absence de preuve du bon fonctionnement lors d''un audit.'], ARRAY['Planifier des tests périodiques de tous les systèmes d''alarme et consigner les résultats.','Corriger rapidement les défauts constatés et suivre la maintenance.']),
  ('REG 13-2', 'Une partie du matériel est installée hors de salles sécurisées, ou des portes et fenêtres de zones sécurisées permettent l''accès ou la connexion au matériel depuis l''extérieur ; les issues de secours ne sont pas prévues sur tous les sites.', ARRAY['Accès au matériel ou connexion illicite depuis l''extérieur de la zone.','Évacuation difficile des personnes en cas de sinistre.'], ARRAY['Regrouper tout le matériel dans des salles sécurisées.','Sécuriser ou condamner les portes et fenêtres donnant accès au matériel et prévoir des issues de secours sur chaque site.']),
  ('REG 13-3', 'Les dispositifs de détection et de lutte contre l''incendie (détecteurs de fumée, extincteurs) sont présents mais leur contrôle et leur test ne sont pas réalisés régulièrement ou pas tracés ; certains extincteurs sont périmés.', ARRAY['Un détecteur ou extincteur défaillant ne fonctionne pas lors d''un incendie.','Propagation du feu aux équipements du SI.'], ARRAY['Planifier la vérification et le test périodiques des détecteurs et extincteurs avec un registre d''entretien.','Remplacer immédiatement les équipements périmés ou défectueux.']),
  ('REG 13-4', 'Les sites sensibles contiennent certains matériels inflammables (mobilier en bois, rideaux, tapis) ou ne présentent pas partout une construction en briques réfractaires.', ARRAY['Propagation plus rapide d''un début d''incendie dans la salle.','Dégâts accrus sur les équipements du SI.'], ARRAY['Retirer des sites sensibles tout matériel inflammable (bois, rideaux, tapis).','Évaluer la résistance au feu de la construction et planifier les travaux nécessaires.']),
  ('REG 13-5', 'Les installations électriques ne respectent pas intégralement les spécifications des fabricants ni les normes de sécurité du fournisseur d''électricité (surcharges de prises, rallonges, câblage non conforme).', ARRAY['Surchauffe ou court-circuit pouvant déclencher un incendie.','Pannes électriques répétées sur les équipements.'], ARRAY['Mettre en conformité les installations avec les spécifications des fabricants et les normes locales.','Supprimer les surcharges et rallonges non conformes dans les locaux techniques.']),
  ('REG 13-6', 'Les installations électriques (éclairage, interrupteurs, câbles, générateur de secours) sont inspectées et testées de façon irrégulière, sans programme ni trace des vérifications.', ARRAY['Des défauts évolutifs ne sont pas détectés avant la panne ou l''incendie.','Le générateur peut s''avérer inopérant lorsqu''il est requis.'], ARRAY['Établir un calendrier d''inspection et de test périodiques des installations électriques et du générateur.','Consigner les résultats et suivre la correction des anomalies.']),
  ('REG 13-7', 'Un générateur de secours existe mais sa capacité, son autonomie en carburant ou ses essais périodiques ne garantissent pas une alimentation d''urgence fiable pour l''ensemble des équipements concernés.', ARRAY['Le générateur peut ne pas démarrer ou ne pas couvrir la charge lors d''une coupure.','Arrêt des services critiques après épuisement du carburant.'], ARRAY['Dimensionner le générateur sur la charge critique et maintenir un stock de carburant suffisant.','Effectuer des essais de démarrage et de basculement périodiques et les consigner.']),
  ('REG 13-8', 'Certains équipements sensibles ne bénéficient pas d''une alimentation électrique permanente : onduleurs absents ou en fin de vie, ou autonomie insuffisante pour couvrir la bascule vers le générateur.', ARRAY['Coupures brèves provoquant des arrêts ou corruptions de données.','Redémarrages incontrôlés des équipements critiques.'], ARRAY['Équiper tous les équipements sensibles d''onduleurs dimensionnés et remplacer les batteries en fin de vie.','Surveiller l''état et l''autonomie des onduleurs et les tester périodiquement.']),
  ('REG 13-9', 'Le matériel des sites sensibles n''est surélevé que partiellement et la détection de fuite d''eau ne couvre pas tous les locaux concernés (équipements posés au sol, capteurs absents sous le faux plancher ou près des canalisations).', ARRAY['Immersion d''équipements posés au sol lors d''une infiltration ou d''une fuite non détectée.','Détection tardive d''une fuite, aggravant les dégâts matériels et la durée d''indisponibilité.'], ARRAY['Installer tous les équipements des sites sensibles sur racks ou supports surélevés.','Étendre les capteurs de fuite d''eau aux zones à risque avec alerte vers une personne d''astreinte.']),
  ('REG 13-10', 'La climatisation et la ventilation des locaux techniques sont en place mais leur entretien n''est pas vérifié régulièrement et le suivi de la température et de l''humidité est incomplet (pas de relevés ou capteurs partiels).', ARRAY['Dérive thermique non détectée entraînant des arrêts ou un vieillissement prématuré des équipements.','Panne de climatisation découverte tardivement, après interruption de service.'], ARRAY['Planifier une maintenance préventive documentée des systèmes de climatisation et de ventilation.','Installer des capteurs de température et d''humidité avec seuils d''alerte et relevés conservés.']),
  ('REG 13-11', 'Le site de reprise sur sinistre ou de stockage des données existe mais sa distance au site principal est insuffisante (même zone géographique, mêmes risques d''inondation ou de coupure électrique).', ARRAY['Sinistre régional affectant simultanément le site principal et le site de secours.','Indisponibilité des sauvegardes en cas d''événement touchant toute la zone.'], ARRAY['Évaluer les risques communs aux deux sites et déplacer le site de secours dans une zone géographique distincte.','Valider la distance retenue dans le plan de continuité d''activité.']),
  ('REG 13-12', 'Les matériels et supports défectueux ou mis au rebut sont stockés dans une pièce dédiée mais celle-ci n''est pas verrouillée en permanence ou son accès n''est pas restreint.', ARRAY['Vol de disques défectueux contenant encore des données récupérables.','Réutilisation non contrôlée de pièces ou supports mis au rebut.'], ARRAY['Verrouiller en permanence la pièce de stockage et limiter les clés aux personnes autorisées.','Tenir un inventaire des matériels et supports mis au rebut.']),
  ('REG 13-13', 'Certains racks et salles d''équipements portent encore des étiquettes descriptives (noms de systèmes, adresses IP ou numéros de ports) visibles de l''extérieur.', ARRAY['Aide à la reconnaissance des équipements critiques par un visiteur ou un prestataire malveillant.','Divulgation d''adresses IP et de la topologie du réseau.'], ARRAY['Retirer les inscriptions décrivant le rôle, les adresses IP et les ports des racks et portes.','Remplacer par un repérage codifié dont la table de correspondance reste confidentielle.']),
  ('REG 13-14', 'Le nettoyage des équipements et des salles techniques est réalisé de façon irrégulière, sans calendrier défini, laissant de la poussière sur certains matériels et filtres.', ARRAY['Surchauffe des équipements par obstruction des ventilateurs et filtres.','Pannes matérielles prématurées liées à l''encrassement.'], ARRAY['Établir un calendrier de nettoyage régulier des équipements et des filtres.','Tracer les interventions de nettoyage dans un registre.']),
  ('REG 13-15', 'L''interdiction d''exercer des activités non prévues dans les salles abritant des équipements sensibles n''est pas formalisée ou appliquée de façon homogène (usage ponctuel comme bureau ou stockage).', ARRAY['Manipulation accidentelle d''équipements par du personnel non concerné.','Présence prolongée de personnes sans lien avec l''exploitation dans une zone sensible.'], ARRAY['Formaliser dans une règle écrite les seules activités autorisées dans les salles sensibles.','Afficher la règle à l''entrée et la rappeler au personnel et aux prestataires.']),
  ('REG 13-16', 'L''interdiction de manger, boire et fumer dans la zone sécurisée n''est pas systématiquement affichée ni respectée ; des restes de consommation y ont été constatés.', ARRAY['Renversement de liquide sur des équipements électriques ou informatiques.','Départ de feu ou déclenchement de détection incendie lié à la fumée.'], ARRAY['Afficher l''interdiction à tous les accès de la zone sécurisée.','Sensibiliser le personnel et sanctionner les manquements constatés.']),
  ('REG 14-1', 'Les lignes électriques et de télécommunication reliées aux systèmes d''information ne sont enterrées que partiellement, alors qu''un enfouissement serait possible sur certains tronçons.', ARRAY['Rupture de liaison par intempéries, choc ou vandalisme sur les tronçons aériens.','Interception ou sabotage facilité sur les tronçons exposés.'], ARRAY['Recenser les tronçons aériens et enterrer ceux pour lesquels c''est techniquement réalisable.','Protéger mécaniquement les tronçons qui ne peuvent être enterrés.']),
  ('REG 14-2', 'Les câbles électriques et de télécommunication sont séparés de façon incomplète : certains passages de câbles les font cheminer côte à côte sans écartement ni blindage.', ARRAY['Interférences électromagnétiques dégradant les liaisons réseau.','Erreurs de transmission difficiles à diagnostiquer.'], ARRAY['Séparer physiquement les cheminements électriques et de télécommunication sur les zones concernées.','Utiliser un blindage ou un écartement approprié quand la séparation n''est pas possible.']),
  ('REG 14-3', 'Les câbles de télécommunication sont en conduits seulement en partie et la redondance des liaisons n''est pas assurée sur tous les segments critiques.', ARRAY['Rupture d''un câble exposé coupant une liaison sans chemin de secours.','Délais de rétablissement allongés en cas de panne de câblage.'], ARRAY['Placer tous les câbles de télécommunication dans des conduits adaptés.','Doubler par des liaisons redondantes les segments critiques.']),
  ('REG 14-4', 'Les câbles électriques sont placés dans des conduits non systématiquement appropriés : certains tronçons restent apparents ou dans des gaines inadaptées.', ARRAY['Dégradation mécanique d''un câble provoquant une coupure ou un court-circuit.','Contact accidentel avec des câbles sous tension lors d''interventions.'], ARRAY['Poser les tronçons apparents dans des conduits normalisés.','Contrôler périodiquement l''état des conduits et des câbles.']),
  ('REG 14-5', 'Les panneaux de brassage et salles de câblage sont isolés des zones d''accueil du public mais leur accès n''est contrôlé que de façon partielle (porte non verrouillée ou clés non suivies).', ARRAY['Débranchement ou rebranchement non autorisé de câbles de brassage.','Accès non tracé aux locaux de câblage.'], ARRAY['Verrouiller les panneaux de brassage et salles de câblage avec gestion nominative des clés ou badges.','Tracer les accès à ces locaux.']),
  ('REG 14-6', 'L''accès aux panneaux de répartition électrique et aux chambres de câblage est limité sans être strictement contrôlé : la liste du personnel autorisé n''est pas tenue à jour.', ARRAY['Manœuvre non autorisée sur un disjoncteur provoquant une coupure.','Impossibilité d''identifier l''auteur d''une intervention sur l''alimentation.'], ARRAY['Établir et mettre à jour la liste du personnel autorisé à accéder aux panneaux électriques.','Verrouiller les panneaux et chambres de câblage et tracer les accès.']),
  ('REG 14-7', 'Les sites sensibles ne sont équipés que partiellement de protection contre la foudre : paratonnerre présent sans parafoudres sur les matériels, ou inversement, sans contrôle périodique.', ARRAY['Surtension endommageant des équipements non protégés lors d''un orage.','Protection foudre dégradée par absence de vérification de l''installation.'], ARRAY['Compléter l''installation par paratonnerre et parafoudres sur tous les sites sensibles.','Faire vérifier périodiquement les dispositifs de protection foudre.']),
  ('REG 15-1', 'Les opérations de maintenance sont effectuées par du personnel majoritairement identifié, mais la liste des intervenants autorisés n''est pas formalisée ni tenue à jour.', ARRAY['Intervention d''une personne non habilitée sur un équipement sensible.','Difficulté à établir la responsabilité en cas d''incident après maintenance.'], ARRAY['Établir et tenir à jour la liste des intervenants de maintenance autorisés.','Vérifier l''identité et l''habilitation avant toute intervention.']),
  ('REG 15-2', 'Des contrats de maintenance existent avec des fournisseurs accrédités, mais pour certains matériels le contrat n''a pas été établi dès la mise en service ou est expiré.', ARRAY['Période sans support lors de pannes sur du matériel non couvert.','Recours à des intervenants non accrédités faute de contrat valide.'], ARRAY['Contractualiser la maintenance de chaque matériel dès sa mise en service.','Suivre les échéances des contrats et les renouveler avant expiration.']),
  ('REG 15-3', 'Les contrats de maintenance ne précisent pas toutes les clauses attendues (temps de réponse, disponibilité, politique de rechange ou modalités de paiement) ou ne sont pas approuvés formellement par le responsable de l''entité.', ARRAY['Délais de réparation non maîtrisés faute d''engagement mesurable.','Contrat engageant l''entité sans validation de sa direction.'], ARRAY['Compléter les contrats avec qualité de service, disponibilité, temps de réponse et politique de rechange.','Faire approuver chaque contrat par le responsable de l''entité.']),
  ('REG 15-4', 'Un registre de maintenance existe mais il est incomplet : les paiements, la qualité, la performance ou l''expiration du contrat ne sont pas systématiquement renseignés.', ARRAY['Impossibilité de vérifier la qualité des prestations et les paiements effectués.','Expiration de contrat non anticipée.'], ARRAY['Compléter le registre avec travaux, paiements, qualité, performance et échéance du contrat.','Contrôler périodiquement la tenue du registre.']),
  ('REG 15-5', 'Le travail des fournisseurs de maintenance est approuvé de façon irrégulière par les administrateurs systèmes, réseaux ou bases de données, et le registre d''approbation est partiel.', ARRAY['Prestation non conforme acceptée sans vérification technique.','Absence de preuve de la validation en cas de litige.'], ARRAY['Faire valider systématiquement chaque intervention par l''administrateur concerné.','Tenir un registre des approbations.']),
  ('REG 15-6', 'Les interventions de maintenance sont supervisées de manière inégale : les ASSI ne sont pas toujours présents et la vérification de l''absence de copie de fichiers ou de programmes n''est pas systématique.', ARRAY['Copie de données ou installation de programme par un prestataire non détectée.','Actions non conformes sur un système lors d''une intervention non surveillée.'], ARRAY['Exiger la présence d''un ASSI pendant toute intervention d''un prestataire.','Vérifier en fin d''intervention qu''aucun fichier ni programme n''a été copié.']),
  ('REG 15-7', 'Les dossiers de maintenance sont conservés de manière dispersée ou incomplète, certains rapports d''intervention étant manquants.', ARRAY['Historique des pannes incomplet, nuisant à l''analyse des défaillances récurrentes.','Preuves manquantes en cas de litige avec un fournisseur.'], ARRAY['Centraliser les dossiers de maintenance dans un espace dédié.','Définir une durée de conservation et s''assurer de la complétude des rapports.']),
  ('REG 15-8', 'Avant remise d''un équipement en réparation, la sauvegarde des données est faite de façon inégale et la suppression sécurisée n''est pas systématique ni tracée.', ARRAY['Données résiduelles lisibles par le réparateur.','Perte de données non sauvegardées lors de la réparation.'], ARRAY['Rendre obligatoires la sauvegarde puis la suppression sécurisée avant toute remise en réparation.','Consigner l''opération dans le dossier de l''équipement.']),
  ('REG 16-1', 'Les supports amovibles contenant des données sensibles ne sont rangés en coffre ou armoire fermée que partiellement ; certains restent sur les bureaux ou dans des tiroirs non verrouillés.', ARRAY['Vol ou perte de supports contenant des informations sensibles.','Copie discrète de données depuis des supports laissés accessibles.'], ARRAY['Ranger tous les supports amovibles sensibles dans un coffre ou une armoire fermée à clé.','Inventorier ces supports et contrôler leur rangement.']),
  ('REG 16-2', 'Après les heures de travail, les clés des locaux, coffres et armoires sont conservées dans un endroit peu sécurisé ou dont l''accès n''est pas limité aux seules personnes autorisées.', ARRAY['Utilisation des clés par du personnel non autorisé hors des heures de travail.','Duplication de clés sans contrôle.'], ARRAY['Conserver les clés dans un meuble sécurisé accessible aux seules personnes autorisées.','Tenir un registre de remise et de restitution des clés.']),
  ('REG 16-3', 'Les fichiers classifiés périmés sont supprimés logiquement, mais l''effacement physique n''est pas systématique, laissant des données récupérables sur certains supports.', ARRAY['Récupération de fichiers classifiés supprimés par un outil de récupération.','Fuite d''informations lors de la réaffectation ou de la mise au rebut d''un support.'], ARRAY['Appliquer un effacement physique sécurisé (écrasement ou destruction) à tous les fichiers classifiés périmés.','Définir une procédure d''effacement et en tracer l''exécution.']),
  ('REG 16-4', 'Des documents sensibles imprimés, copiés ou numérisés restent parfois dans les bacs des imprimantes, photocopieuses ou scanneurs après utilisation.', ARRAY['Lecture de documents sensibles par des personnes de passage.','Perte de confidentialité sans possibilité d''identifier la source.'], ARRAY['Rappeler l''obligation de retirer immédiatement les documents des appareils.','Contrôler régulièrement les bacs et détruire les documents oubliés.']),
  ('REG 16-5', 'Les ordinateurs et terminaux ne se verrouillent pas systématiquement après une courte période d''inactivité ; le verrouillage automatique est absent ou paramétré avec un délai excessif sur certains postes.', ARRAY['Accès non autorisé à une session laissée ouverte en l''absence de l''utilisateur.','Actions malveillantes imputées à tort au titulaire de la session.'], ARRAY['Configurer un verrouillage automatique avec mot de passe après un délai court sur tous les postes.','Sensibiliser les agents à verrouiller leur poste en le quittant.']),
  ('REG 16-6', 'L''interdiction d''utiliser sans autorisation les photocopieurs, scanneurs et appareils photo numériques est formulée sans mécanisme de contrôle, et des reproductions non autorisées ne sont pas détectées.', ARRAY['Reproduction de documents sensibles sans trace.','Fuite d''informations par photographie ou numérisation discrète.'], ARRAY['Formaliser l''interdiction dans une règle écrite communiquée à tout le personnel.','Mettre en place un contrôle d''accès ou de code sur les appareils de reproduction.']),
  ('REG 16-7', 'Des imprimantes avec identification par code personnel existent mais ne sont pas déployées partout ou la fonction n''est pas activée pour tous les utilisateurs.', ARRAY['Récupération de documents imprimés par une autre personne que l''émetteur.','Documents sensibles laissés dans les bacs, sans protection.'], ARRAY['Activer l''impression sécurisée par code personnel sur toutes les imprimantes concernées.','Rendre cette fonction obligatoire pour les impressions sensibles.']),
  ('REG 17-1', 'Les mesures de sécurité propres aux applications métier (contrôle d''accès, traçabilité, protection des données) sont définies de façon partielle et ne couvrent pas toutes les applications.', ARRAY['Applications exploitées avec des niveaux de protection hétérogènes selon les équipes.','Traitement d''informations sensibles sans mesures minimales vérifiables.'], ARRAY['Formaliser un référentiel de mesures de sécurité applicables à chaque application métier, selon la classification des données.','Vérifier l''application de ces mesures lors de chaque recette et revue annuelle.']),
  ('REG 17-2', 'Le principe du besoin d''en connaître est appliqué de façon incomplète : certains accès aux informations sensibles sont accordés sans justification formelle du besoin ni habilitation vérifiée.', ARRAY['Accès d''agents non habilités à des informations sensibles.','Divulgation d''informations par des utilisateurs n''ayant pas le besoin d''en connaître.'], ARRAY['Subordonner chaque accès aux informations sensibles à une habilitation et à un besoin d''en connaître validés par le propriétaire de l''information.','Réviser les droits existants au regard de ce critère.']),
  ('REG 17-3', 'L''accès aux moyens de traitement des informations sensibles n''est pas systématiquement conditionné à l''habilitation et au besoin d''utiliser du demandeur.', ARRAY['Utilisation de serveurs ou postes sensibles par des agents sans nécessité professionnelle.','Augmentation de la surface d''attaque sur les moyens de traitement.'], ARRAY['Exiger une justification du besoin d''utiliser pour tout accès aux moyens de traitement sensibles.','Recenser et réviser les comptes disposant d''un accès à ces moyens.']),
  ('REG 17-4', 'Le cloisonnement des rôles pour le contrôle des accès est partiel : certains utilisateurs cumulent des rôles incompatibles (demande, validation, administration).', ARRAY['Possibilité de réaliser seul une opération sensible de bout en bout sans contrôle.','Fraude ou erreur non détectée faute de séparation des tâches.'], ARRAY['Cartographier les rôles et identifier les cumuls incompatibles.','Appliquer la séparation des tâches et compenser les cas impossibles par des contrôles tracés.']),
  ('REG 17-5', 'Les droits d''accès des utilisateurs ne sont pas revus ni mis à jour régulièrement ; des droits obsolètes subsistent après les mouvements de personnel.', ARRAY['Maintien de droits indus (départs, mutations) exploitables à des fins malveillantes.','Accumulation de privilèges contraire au moindre privilège.'], ARRAY['Instaurer une revue périodique et tracée des droits, validée par les responsables.','Déclencher la mise à jour des droits à chaque arrivée, mutation et départ.']),
  ('REG 17-6', 'Les privilèges et droits d''accès ne sont pas systématiquement revus lors des changements de poste ; certains agents conservent les droits de leur ancienne fonction.', ARRAY['Cumul de droits d''anciennes et nouvelles fonctions.','Accès à des informations sans rapport avec le poste actuel.'], ARRAY['Associer toute mutation à une revue des droits avec retrait des accès non nécessaires.','Tracer la revue dans le dossier de mutation.']),
  ('REG 18-1', 'Le contrôle d''accès aux fonctions des applications et systèmes est mis en œuvre de façon inégale : certaines fonctions d''administration sont accessibles sans profil dédié.', ARRAY['Exécution de fonctions sensibles par des utilisateurs ordinaires.','Modification non autorisée de la configuration applicative.'], ARRAY['Définir des profils applicatifs limitant l''accès aux fonctions selon les rôles.','Tester les restrictions d''accès aux fonctions d''administration lors des recettes.']),
  ('REG 18-2', 'Les droits des utilisateurs ne sont pas différenciés finement (lecture, écriture, suppression) : des utilisateurs disposent de droits d''écriture ou de suppression sans nécessité.', ARRAY['Suppression ou modification accidentelle ou malveillante de données.','Atteinte à l''intégrité des informations.'], ARRAY['Paramétrer des droits distincts en lecture, écriture et suppression par profil.','Revoir les profils pour retirer les droits d''écriture et de suppression non justifiés.']),
  ('REG 18-3', 'L''accès à certaines applications n''est pas restreint par un mécanisme de connexion sécurisée : des accès sont possibles sans authentification ou via des comptes partagés.', ARRAY['Accès anonyme ou non imputable aux données applicatives.','Usage de comptes partagés rendant la traçabilité impossible.'], ARRAY['Imposer une authentification individuelle sur toutes les applications.','Supprimer les comptes génériques ou partagés.']),
  ('REG 18-4', 'L''authentification forte n''est pas exigée de façon systématique pour l''accès aux données classifiées : elle n''est déployée que sur une partie des applications ou profils.', ARRAY['Accès non autorisé aux informations sensibles en cas de vol ou réutilisation d''identifiant.','Protection hétérogène des données de même classification.'], ARRAY['Étendre l''authentification multifacteur à toutes les applications traitant des données classifiées.','Prioriser les comptes à privilèges et les accès distants.']),
  ('REG 18-5', 'Le nombre de tentatives de connexion échouées aux applications n''est pas limité : aucun verrouillage ni temporisation n''est configuré.', ARRAY['Attaques par force brute ou bourrage d''identifiants sur les comptes applicatifs.','Compromission de comptes sans alerte.'], ARRAY['Configurer un verrouillage temporaire ou une temporisation après un nombre défini d''échecs.','Alerter l''administrateur en cas de tentatives répétées.']),
  ('REG 18-6', 'Les messages affichés lors d''une connexion échouée révèlent des indications exploitables (identifiant inexistant, mot de passe incorrect, version du système).', ARRAY['Énumération des comptes valides par un attaquant.','Facilitation des attaques ciblées sur les identifiants.'], ARRAY['Uniformiser les messages d''échec par un libellé générique.','Supprimer l''affichage des informations techniques sur les pages de connexion.']),
  ('REG 18-7', 'Des mots de passe par défaut fournis à l''installation ou à la création de comptes n''ont pas été modifiés sur certains systèmes et applications.', ARRAY['Prise de contrôle de systèmes via des identifiants publics du constructeur.','Compromission d''équipements d''infrastructure.'], ARRAY['Imposer le changement des mots de passe par défaut à la mise en service et à la première connexion.','Scanner régulièrement les systèmes pour détecter les identifiants par défaut.']),
  ('REG 18-8', 'Les sessions inactives ne sont pas fermées automatiquement après un délai défini et les tentatives de connexion ne sont pas toutes journalisées.', ARRAY['Utilisation de sessions laissées ouvertes sur des postes non surveillés.','Impossibilité de reconstituer les tentatives d''accès lors d''une enquête.'], ARRAY['Configurer une déconnexion automatique après une durée d''inactivité définie.','Journaliser toutes les tentatives de connexion, réussies et échouées, et conserver les traces.']),
  ('REG 18-9', 'La politique de mots de passe est insuffisante : exigences de robustesse faibles, absence de renouvellement périodique défini ou transmission possible en clair.', ARRAY['Compromission de mots de passe faibles par devinette ou force brute.','Interception de mots de passe transmis sans chiffrement.'], ARRAY['Définir et appliquer techniquement une politique de robustesse et de renouvellement périodique.','Imposer des protocoles chiffrés pour toute authentification.']),
  ('REG 18-10', 'L''installation de logiciels n''est pas formellement interdite sans l''autorisation de l''ASSI : les utilisateurs disposent de droits locaux leur permettant d''installer des logiciels non validés.', ARRAY['Introduction de logiciels malveillants ou sans licence.','Perte de maîtrise du parc applicatif.'], ARRAY['Retirer les droits d''administration locale aux utilisateurs standard.','Formaliser une procédure d''autorisation préalable par l''ASSI et contrôler le parc.']),
  ('REG 18-11', 'Des applications et utilitaires non indispensables restent installés sur les postes et serveurs, sans revue de leur nécessité.', ARRAY['Multiplication des vulnérabilités exploitables.','Services inutiles exposés sur les systèmes.'], ARRAY['Établir une configuration de base minimale et désinstaller les composants superflus.','Contrôler périodiquement la conformité des systèmes à cette base.']),
  ('REG 18-12', 'L''accès au code source des applications n''est pas contrôlé de façon rigoureuse : des droits en écriture sont accordés largement et les modifications ne sont pas toutes tracées.', ARRAY['Altération non détectée du code source.','Introduction de portes dérobées dans les applications.'], ARRAY['Restreindre l''accès au code source par profils dans un dépôt versionné.','Tracer toutes les modifications et exiger une revue avant intégration.']),
  ('REG 19-1', 'Aucune politique d''accès aux réseaux de l''entité ne précise les exigences d''authentification des utilisateurs.', ARRAY['Connexion au réseau d''équipements ou de personnes non authentifiés.','Application disparate des règles d''accès selon les sites.'], ARRAY['Rédiger une politique d''accès réseau définissant l''authentification requise par type d''accès.','Mettre en œuvre un contrôle d''accès au réseau (802.1X ou équivalent) pour les accès internes et distants.']),
  ('REG 19-2', 'Les responsabilités et procédures de gestion des équipements réseau ne sont pas formalisées : administration, modification et supervision reposent sur des pratiques informelles.', ARRAY['Modifications de configuration non maîtrisées provoquant des indisponibilités.','Absence de responsable identifié en cas d''incident réseau.'], ARRAY['Désigner les responsables de chaque équipement réseau.','Documenter les procédures d''administration, de changement et de sauvegarde des configurations.']),
  ('REG 19-3', 'La conformité des moyens de transmission de l''information à la législation en vigueur n''est pas vérifiée ni documentée.', ARRAY['Utilisation de moyens de transmission contraires à la réglementation.','Exposition juridique de l''entité en cas de contrôle ou d''incident.'], ARRAY['Recenser les moyens de transmission utilisés et vérifier leur conformité légale.','Interdire ou remplacer les moyens non conformes.']),
  ('REG 19-4', 'Les activités réseau ne font pas l''objet d''une surveillance et d''une journalisation complètes : certains segments ou équipements ne produisent pas de journaux exploitables.', ARRAY['Intrusions ou exfiltrations non détectées sur les segments non supervisés.','Absence de traces pour l''investigation d''incidents.'], ARRAY['Activer la journalisation sur tous les équipements réseau et centraliser les journaux.','Définir des seuils d''alerte et une revue régulière des événements.']),
  ('REG 19-5', 'Les données transmises via les réseaux publics ne sont pas protégées selon leur niveau de classification et les réseaux de l''État ne sont pas privilégiés pour les échanges hors entité.', ARRAY['Interception de données sensibles en transit sur Internet.','Exposition d''informations classifiées lors d''échanges externes.'], ARRAY['Définir les protections requises (chiffrement, VPN) par niveau de classification.','Utiliser les réseaux de l''État pour les transmissions hors entité lorsque possible.']),
  ('REG 19-6', 'Les services réseau fournis ne sont pas sécurisés par des fonctions d''authentification, d''intégrité, de chiffrement et de non-répudiation, et ces exigences ne sont pas convenues avec les fournisseurs.', ARRAY['Altération ou écoute des flux sans détection.','Répudiation d''échanges faute de preuve.'], ARRAY['Inscrire les exigences de sécurité dans les contrats et SLA des fournisseurs de services réseau.','Activer authentification, chiffrement et contrôle des connexions sur les services réseau.']),
  ('REG 19-7', 'Le déploiement des réseaux sans fil n''a pas fait l''objet d''une analyse de risques spécifique et le réseau Wi-Fi n''est pas segmenté du réseau interne.', ARRAY['Accès au réseau interne depuis le Wi-Fi par un tiers.','Compromission via des points d''accès mal sécurisés.'], ARRAY['Réaliser une analyse de risques dédiée aux réseaux sans fil.','Segmenter le Wi-Fi (invités et interne) et imposer un chiffrement et une authentification robustes.']),
  ('REG 19-8', 'Les réseaux informatiques ne sont pas cloisonnés selon un critère défini (service, niveau de sécurité) : le réseau est largement à plat.', ARRAY['Propagation latérale rapide d''une compromission.','Accès des utilisateurs à des zones sensibles sans lien avec leur fonction.'], ARRAY['Définir un critère de segmentation et séparer les zones par VLAN et pare-feu.','Filtrer les flux inter-zones selon le principe du strict nécessaire.']),
  ('REG 19-9-1', 'Les algorithmes de chiffrement utilisés ne sont pas vérifiés comme labellisés par la Commission nationale de cryptologie ; leur conformité à la loi 2008-41 n''est pas démontrée.', ARRAY['Utilisation d''algorithmes non conformes à la réglementation.','Niveau de protection cryptographique non maîtrisé.'], ARRAY['Inventorier les algorithmes employés et les confronter à la liste de la Commission nationale de cryptologie.','Remplacer les algorithmes non labellisés.']),
  ('REG 19-9-5', 'La messagerie électronique n''est pas protégée par une authentification forte et un chiffrement : l''accès repose sur un simple mot de passe et les messages sensibles circulent sans chiffrement.', ARRAY['Prise de contrôle de boîtes de messagerie par vol d''identifiants.','Interception ou lecture de messages confidentiels.'], ARRAY['Activer l''authentification multifacteur sur la messagerie.','Imposer le chiffrement des flux (TLS) et du contenu sensible.']),
  ('REG 19-9-7', 'Les disques des systèmes contenant des informations sensibles (postes portables, serveurs) ne sont pas chiffrés.', ARRAY['Divulgation des données en cas de perte ou vol d''un équipement.','Extraction de données par accès physique au support.'], ARRAY['Déployer un chiffrement de disque, en priorité sur les portables et les systèmes sensibles.','Gérer les clés de récupération de façon centralisée.']),
  ('REG 19-9-11', 'Les longueurs de clés de chiffrement utilisées ne sont pas alignées sur les recommandations de la Commission nationale de cryptologie ; certaines clés sont trop courtes.', ARRAY['Affaiblissement du chiffrement face au calcul moderne.','Déchiffrement possible des données par un attaquant.'], ARRAY['Recenser les longueurs de clés en usage et les comparer aux recommandations.','Migrer les clés insuffisantes vers des longueurs conformes.']),
  ('REG 19-9-12', 'Il n''existe pas de politique rigoureuse de gestion des clés de chiffrement : génération, stockage, rotation et destruction des clés ne sont pas encadrés.', ARRAY['Compromission ou perte de clés rendant les données inexploitables ou exposées.','Clés stockées en clair ou sans sauvegarde sécurisée.'], ARRAY['Formaliser une politique couvrant tout le cycle de vie des clés.','Stocker les clés dans un coffre ou HSM avec accès restreint et tracé.']),
  ('REG 20-1', 'Il n''existe pas de procédures documentées d''installation et de configuration des systèmes ; ces opérations reposent sur le savoir-faire individuel des administrateurs.', ARRAY['Configurations hétérogènes et non reproductibles d''un système à l''autre.','Paramètres de sécurité omis ou mal appliqués lors des installations.','Perte de savoir-faire en cas d''indisponibilité ou de départ d''un administrateur.'], ARRAY['Rédiger et valider une procédure d''installation et de configuration par type de système.','Intégrer dans chaque procédure les paramètres de durcissement exigés.','Tenir les procédures sous contrôle de version et accessibles aux exploitants.']),
  ('REG 20-2', 'Aucune procédure documentée de redémarrage et de récupération n''est définie ou appliquée pour les systèmes en cas de défaillance.', ARRAY['Remise en service lente et improvisée après une panne.','Redémarrage dans un ordre erroné provoquant corruption ou perte de données.','Allongement de l''indisponibilité des services critiques.'], ARRAY['Documenter pour chaque système les étapes de redémarrage et de récupération, avec les responsabilités.','Tester ces procédures lors d''exercices périodiques.','Rendre les procédures disponibles hors ligne pour les cas de sinistre.']),
  ('REG 20-3', 'Les systèmes ne disposent pas de procédure documentée de sauvegarde et de maintenance, ou celle-ci n''est pas appliquée.', ARRAY['Sauvegardes irrégulières ou incomplètes selon les systèmes.','Maintenance non planifiée entraînant des pannes évitables.','Dépendance à la mémoire des exploitants.'], ARRAY['Formaliser par système la procédure de sauvegarde (périmètre, fréquence, rétention) et de maintenance.','Désigner les responsables et contrôler l''application effective.','Réviser les procédures à chaque évolution du système.']),
  ('REG 20-4', 'Les contacts du support technique (éditeurs, prestataires, constructeurs) ne sont pas répertoriés ou ne sont pas tenus à jour.', ARRAY['Délai accru de résolution d''un incident d''exploitation.','Appel à un support dont le contrat ou les coordonnées sont périmés.','Indisponibilité prolongée en dehors des heures ouvrées.'], ARRAY['Établir un annuaire des supports techniques avec niveaux de service et astreintes.','Mettre à jour l''annuaire à chaque changement de contrat ou de prestataire.','Diffuser l''annuaire aux équipes d''exploitation.']),
  ('REG 20-5', 'Les normes de sécurité applicables aux équipements ne sont pas documentées, ou leur respect n''est pas suivi.', ARRAY['Équipements déployés avec des configurations faibles par défaut.','Écarts de sécurité non détectés entre équipements de même type.','Surface d''attaque accrue sur des équipements non durcis.'], ARRAY['Définir des référentiels de configuration sécurisée par type d''équipement.','Vérifier périodiquement la conformité des équipements à ces référentiels.','Traiter et tracer les écarts constatés.']),
  ('REG 20-6', 'L''installation de logiciels sans rapport avec l''activité de l''entité n''est pas interdite ni techniquement empêchée sur les postes et serveurs.', ARRAY['Introduction de logiciels vulnérables ou malveillants.','Fuite de données via des applications non maîtrisées.','Dégradation des performances et de la stabilité des postes.'], ARRAY['Formaliser dans une politique l''interdiction d''installer des logiciels étrangers à l''activité.','Retirer les droits d''installation aux utilisateurs standards.','Contrôler périodiquement l''inventaire logiciel des postes.']),
  ('REG 20-7', 'L''usage de logiciels non autorisés ou sans licence authentique n''est ni interdit ni contrôlé ; aucun inventaire des licences ne permet de le détecter.', ARRAY['Sanctions juridiques et financières pour contrefaçon.','Logiciels piratés porteurs de codes malveillants.','Absence de correctifs et de support sur des logiciels illicites.'], ARRAY['Interdire formellement les logiciels non autorisés ou sans licence.','Tenir un inventaire des logiciels autorisés et des licences associées.','Auditer régulièrement les postes et traiter les écarts.']),
  ('REG 20-8', 'Les procédures d''exploitation ne font l''objet d''aucun audit, contrôle ou mise à jour périodique.', ARRAY['Procédures obsolètes ne reflétant plus les systèmes en place.','Écarts entre pratiques réelles et procédures non détectés.','Erreurs d''exploitation répétées faute de retour d''expérience.'], ARRAY['Planifier une revue annuelle des procédures d''exploitation.','Auditer par échantillonnage l''application effective des procédures.','Tracer les révisions et diffuser les versions à jour.']),
  ('REG 21-1', 'Les changements significatifs apportés au SI ne sont ni identifiés ni consignés dans un registre.', ARRAY['Impossibilité de retrouver l''origine d''un dysfonctionnement après modification.','Changements non maîtrisés échappant à tout suivi.','Perte de traçabilité utile aux audits et investigations.'], ARRAY['Mettre en place un registre des changements avec critères de significativité.','Enregistrer pour chaque changement demandeur, date, périmètre et résultat.','Contrôler périodiquement l''exhaustivité du registre.']),
  ('REG 21-2', 'Les changements et leur phase de test ne sont pas planifiés ; ils sont réalisés sans calendrier ni plan de test défini.', ARRAY['Interruptions de service lors de changements réalisés à contretemps.','Défauts non détectés faute de tests préalables.','Conflits entre changements concurrents.'], ARRAY['Établir un planning des changements intégrant une phase de test.','Définir un plan de test et des critères de validation par changement.','Coordonner les fenêtres de maintenance avec les métiers.']),
  ('REG 21-3', 'L''impact des changements sur la sécurité de l''information n''est pas évalué avant leur mise en œuvre.', ARRAY['Introduction de vulnérabilités ou de régressions de sécurité.','Contournement involontaire de mesures de protection existantes.','Découverte tardive d''impacts sur la confidentialité ou la disponibilité.'], ARRAY['Intégrer une analyse d''impact sécurité dans toute demande de changement.','Faire valider cette analyse par le responsable sécurité pour les changements sensibles.','Conserver la trace de l''évaluation dans le dossier de changement.']),
  ('REG 21-4', 'Il n''existe pas de procédure formelle d''autorisation des changements ; ils sont appliqués sans validation préalable tracée.', ARRAY['Modifications non autorisées ou non justifiées en production.','Absence de responsabilité identifiée en cas d''incident.','Contournement des contrôles par des interventions ad hoc.'], ARRAY['Instaurer un processus d''approbation des changements avec comité ou valideur désigné.','Interdire toute mise en production sans autorisation enregistrée.','Auditer la conformité des changements réalisés au processus.']),
  ('REG 21-5', 'Le respect des exigences de sécurité de l''information n''est pas vérifié à l''issue des changements.', ARRAY['Systèmes modifiés remis en service avec une configuration non conforme.','Dérive progressive du niveau de sécurité.','Failles introduites non détectées après changement.'], ARRAY['Définir une liste de contrôles de sécurité à vérifier après chaque changement.','Exiger une recette sécurité avant clôture du changement.','Consigner les résultats et traiter les non-conformités.']),
  ('REG 21-6', 'Les informations détaillées sur les changements apportés ne sont pas communiquées à l''ensemble des personnes concernées.', ARRAY['Utilisateurs et exploitants surpris par des modifications de service.','Mauvaise gestion des incidents liés à un changement non connu.','Support dans l''incapacité d''expliquer le comportement du système.'], ARRAY['Définir une liste de diffusion des changements par périmètre.','Notifier en amont la nature, la date et l''impact attendu des changements.','Mettre à jour la documentation et les procédures concernées.']),
  ('REG 21-7', 'Aucune procédure de repli, avec responsabilités associées, n''est prévue en cas d''échec d''un changement ou d''événement imprévu.', ARRAY['Impossibilité de revenir à un état stable après un changement raté.','Indisponibilité prolongée des services.','Décisions d''abandon prises dans l''urgence sans responsable identifié.'], ARRAY['Prévoir pour chaque changement un plan de retour arrière testable.','Définir les critères d''abandon et les responsables de la décision.','S''assurer de disposer des sauvegardes nécessaires avant le changement.']),
  ('REG 21-8', 'Aucun processus de modification d''urgence n''est défini pour traiter rapidement et de façon contrôlée les changements imposés par un incident.', ARRAY['Interventions d''urgence réalisées sans autorisation ni traçabilité.','Corrections hâtives introduisant de nouvelles failles.','Contournement systématique du processus normal de changement.'], ARRAY['Définir un circuit simplifié d''approbation des changements d''urgence.','Exiger une consignation et une régularisation a posteriori sous délai fixé.','Réaliser une revue des changements d''urgence après clôture de l''incident.']),
  ('REG 22-1', 'Les logiciels de développement et d''exploitation ne sont pas exécutés sur des systèmes et des domaines ou répertoires distincts.', ARRAY['Erreur de développement impactant directement la production.','Accès de développeurs aux ressources d''exploitation.','Propagation d''un code non validé vers les systèmes en service.'], ARRAY['Séparer physiquement ou logiquement les environnements de développement, test et exploitation.','Utiliser des domaines et répertoires distincts avec droits d''accès dédiés.','Documenter la cartographie des environnements.']),
  ('REG 22-2', 'Les modifications des systèmes et applications ne sont pas testées dans un environnement de test avant leur application en exploitation.', ARRAY['Défaillances découvertes directement en production.','Régressions fonctionnelles et de sécurité non anticipées.','Interruptions de service lors des mises en production.'], ARRAY['Mettre à disposition un environnement de test représentatif de la production.','Rendre obligatoire le passage par la recette avant toute mise en production.','Conserver les résultats de test comme preuve de validation.']),
  ('REG 22-3', 'Les activités de développement ne sont pas séparées des activités de test, qui s''exécutent dans les mêmes environnements.', ARRAY['Tests faussés par du code en cours de modification.','Auto-validation par les développeurs de leurs propres livrables.','Instabilité de l''environnement de test.'], ARRAY['Isoler les environnements de développement et de test.','Distinguer les rôles de développeur et de testeur.','Contrôler les transferts de code entre environnements.']),
  ('REG 22-4', 'Des compilateurs, éditeurs et autres outils de développement ou utilitaires système sont accessibles sur les systèmes en exploitation sans nécessité.', ARRAY['Compilation ou modification de code directement en production.','Outils détournés par un attaquant pour étendre une intrusion.','Modifications non tracées hors processus de changement.'], ARRAY['Désinstaller ou restreindre les outils de développement des serveurs de production.','Limiter les utilitaires système aux administrateurs habilités.','Vérifier périodiquement le contenu logiciel des serveurs en exploitation.']),
  ('REG 22-5', 'Les utilisateurs emploient les mêmes profils pour les systèmes en exploitation et de test, et rien ne distingue visuellement les environnements.', ARRAY['Opérations de test exécutées par erreur en production.','Compromission d''un compte de test donnant accès à la production.','Confusion d''environnement lors des manipulations de données.'], ARRAY['Créer des profils et identifiants distincts par environnement.','Afficher des messages ou bandeaux d''identification explicites de l''environnement.','Revoir les droits des profils de test sur la production.']),
  ('REG 22-6', 'Des données sensibles de production sont copiées dans l''environnement de test, qui ne bénéficie pas de mesures de sécurité équivalentes.', ARRAY['Fuite de données sensibles depuis un environnement faiblement protégé.','Accès de testeurs ou développeurs à des données qu''ils ne doivent pas connaître.','Non-conformité à la protection des données personnelles.'], ARRAY['Interdire la copie de données sensibles réelles vers les environnements de test.','Utiliser des jeux de données anonymisés ou fictifs.','Appliquer des mesures équivalentes à la production lorsque la copie est indispensable.']),
  ('REG 23-1', 'Un outil de protection contre les logiciels malveillants n''est pas installé sur l''ensemble des serveurs, ordinateurs fixes et terminaux mobiles.', ARRAY['Infection non détectée des équipements non protégés.','Propagation de logiciels malveillants au reste du réseau.','Compromission de terminaux mobiles hors du périmètre réseau.'], ARRAY['Déployer un antimalware sur tous les serveurs, postes et terminaux mobiles.','Dresser l''inventaire des équipements non couverts et les traiter.','Superviser la couverture via une console centralisée.']),
  ('REG 23-2', 'La mise à jour des outils de protection antimalware n''est pas paramétrée ni assurée par l''utilisateur ou l''administrateur ; des signatures sont obsolètes.', ARRAY['Non-détection des menaces récentes.','Fausse impression de protection.','Infection par des codes malveillants connus mais non reconnus.'], ARRAY['Configurer la mise à jour automatique des signatures et moteurs.','Superviser l''âge des signatures sur le parc.','Désigner un responsable du suivi des équipements en retard.']),
  ('REG 23-3', 'Les logiciels de détection et de réparation ne sont pas installés ou régulièrement mis à jour pour analyser les ordinateurs et supports.', ARRAY['Supports amovibles infectés introduits sans analyse.','Malwares dormants non découverts sur les postes.','Impossibilité de nettoyer rapidement un équipement infecté.'], ARRAY['Planifier des analyses régulières des postes et supports amovibles.','Maintenir à jour les outils de détection et de réparation.','Analyser systématiquement tout support externe avant usage.']),
  ('REG 23-4', 'Aucun mécanisme ne diffuse une alerte à l''ensemble de l''entité lorsqu''un logiciel malveillant est détecté.', ARRAY['Propagation de l''infection faute d''avertissement des autres utilisateurs.','Réaction tardive et non coordonnée.','Réutilisation du vecteur d''attaque par d''autres agents.'], ARRAY['Définir une procédure d''alerte et de diffusion en cas de détection de malware.','Désigner l''émetteur et les canaux de diffusion.','Inclure des consignes de réaction dans l''alerte.']),
  ('REG 23-5', 'Les utilisateurs ne sont pas sensibilisés ni tenus de ne pas ouvrir les courriers électroniques suspects, avec ou sans pièces jointes.', ARRAY['Infection par rançongiciel via une pièce jointe piégée.','Vol d''identifiants par hameçonnage.','Propagation interne depuis un poste compromis.'], ARRAY['Sensibiliser les utilisateurs à l''identification des courriels suspects.','Mettre en place un canal de signalement des courriels douteux.','Réaliser des campagnes de simulation d''hameçonnage.']),
  ('REG 23-6', 'Les serveurs de messagerie ne disposent pas d''anti-spam ni de listes noires en temps réel pour bloquer les spams.', ARRAY['Afflux de spams et de courriels frauduleux vers les utilisateurs.','Vecteur de diffusion de malwares et d''hameçonnage non filtré.','Saturation de la messagerie et perte de productivité.'], ARRAY['Installer un anti-spam sur les serveurs de messagerie.','Activer l''interrogation de listes noires temps réel (RBL).','Surveiller l''efficacité du filtrage et ajuster les règles.']),
  ('REG 23-7', 'Aucun filtre de contenu n''empêche l''accès aux sites web malveillants ou suspects depuis le réseau de l''entité.', ARRAY['Téléchargement de logiciels malveillants depuis des sites compromis.','Redirection vers des sites d''hameçonnage.','Fuite de données vers des sites non maîtrisés.'], ARRAY['Déployer un filtrage web (proxy ou passerelle) basé sur des catégories et des réputations.','Bloquer les sites malveillants connus ou suspectés.','Revoir périodiquement les règles et journaux de filtrage.']),
  ('REG 23-8', 'Il n''existe pas de procédure de continuité d''activité après une attaque par logiciel malveillant, ni de sauvegardes dédiées des logiciels et données nécessaires.', ARRAY['Arrêt prolongé de l''activité après un rançongiciel.','Impossibilité de reconstruire les systèmes faute de sauvegardes saines.','Perte de données sans possibilité de récupération.'], ARRAY['Rédiger un plan de continuité spécifique aux attaques par logiciels malveillants.','Sauvegarder logiciels et données critiques sur des supports isolés.','Tester la procédure de reprise après attaque.']),
  ('REG 23-9', 'Les utilisateurs ne disposent pas de consignes de vigilance contre l''introduction de logiciels malveillants lors des opérations de maintenance et de dépannage.', ARRAY['Introduction de malwares via les outils ou supports des intervenants.','Contournement des protections lors d''une intervention à distance.','Compromission durant une maintenance non supervisée.'], ARRAY['Édicter des règles de vigilance pour les interventions de maintenance et dépannage.','Analyser les outils et supports des intervenants avant connexion.','Superviser les interventions externes.']),
  ('REG 23-10', 'L''exactitude et la provenance des bulletins d''alerte sur les logiciels malveillants ne sont pas vérifiées auprès de sources qualifiées et réputées.', ARRAY['Réaction à de fausses alertes ou canulars.','Mesures inadaptées appliquées sur la foi d''informations erronées.','Menaces réelles non prises en compte.'], ARRAY['Définir la liste des sources de veille reconnues (éditeurs, CERT, publications fiables).','Recouper tout bulletin avant diffusion.','Désigner un responsable de la veille sur les malwares.']),
  ('REG 24-1', 'Les données utilisateurs, configurations, fichiers système et messages électroniques ne sont pas sauvegardés périodiquement selon la fréquence requise (incrémentielle quotidienne pour les données sensibles, complète hebdomadaire) sur des supports dédiés.', ARRAY['Perte de données récentes en cas de panne ou d''attaque.','Impossibilité de reconstruire les systèmes et réseaux sans configurations sauvegardées.','Messagerie non restaurable après incident.'], ARRAY['Mettre en œuvre les cycles de sauvegarde requis : incrémentielle quotidienne et complète hebdomadaire.','Stocker les sauvegardes sur serveurs ou supports dédiés, sur site et hors site.','Superviser les résultats des sauvegardes et traiter les échecs.']),
  ('REG 24-3', 'Le recours au stockage en ligne gratuit proposé par des prestataires privés n''est pas interdit ni bloqué.', ARRAY['Fuite de données de l''entité vers des services non maîtrisés.','Perte de contrôle sur la localisation et la confidentialité des données.','Absence de garantie contractuelle de disponibilité et de restitution.'], ARRAY['Interdire formellement le stockage sur services en ligne gratuits.','Bloquer techniquement l''accès à ces services.','Fournir une solution de stockage officielle.']),
  ('REG 24-4', 'Les sauvegardes contenant des données sensibles ne sont pas chiffrées avec des moyens labellisés par la Commission nationale de cryptologie.', ARRAY['Divulgation des données en cas de vol ou perte d''un support.','Exploitation des sauvegardes par un tiers non autorisé.','Non-conformité aux exigences nationales de cryptologie.'], ARRAY['Chiffrer les sauvegardes de données sensibles avec des solutions labellisées.','Gérer et protéger séparément les clés de chiffrement.','Vérifier la restauration des sauvegardes chiffrées.']),
  ('REG 24-5', 'Les locaux de stockage des sauvegardes de données sensibles ne sont pas sécurisés.', ARRAY['Vol ou altération de supports de sauvegarde.','Destruction par incendie, inondation ou accès non contrôlé.','Perte simultanée des données et de leurs copies.'], ARRAY['Placer les supports dans des locaux à accès restreint et contrôlé.','Assurer une protection contre les risques environnementaux.','Tenir un registre des accès et des mouvements de supports.']),
  ('REG 24-7', 'Aucun test périodique de restauration ne vérifie l''intégrité des données sauvegardées, et leur fréquence n''est pas proportionnée à la sensibilité des systèmes.', ARRAY['Sauvegardes inexploitables découvertes le jour d''un sinistre.','Perte de données irréversible malgré l''existence de sauvegardes.','Dépassement des objectifs de reprise faute de procédure testée.'], ARRAY['Planifier des tests de restauration à fréquence modulée selon la criticité.','Documenter les résultats et corriger les écarts.','Vérifier l''intégrité des données restaurées.']),
  ('REG 25-1', 'Les journaux d''événements sont incomplets : ils n''enregistrent pas l''ensemble des éléments requis (identifiants, date et heure, terminal, tentatives d''accès, modifications de configuration, usage des privilèges).', ARRAY['Impossibilité de reconstituer le déroulement d''un incident.','Absence de preuve d''imputabilité.','Tentatives d''intrusion non tracées.'], ARRAY['Définir le contenu minimal des journaux conformément à l''exigence.','Configurer les systèmes pour enregistrer ces événements.','Vérifier périodiquement la complétude des journaux.']),
  ('REG 25-2', 'Les moyens de journalisation et les journaux ne sont pas protégés contre la falsification et les accès non autorisés.', ARRAY['Effacement ou modification des traces par un attaquant ou un administrateur.','Perte de valeur probante des journaux.','Dissimulation d''une intrusion.'], ARRAY['Centraliser les journaux sur un serveur dédié aux accès restreints.','Mettre en place l''intégrité (écriture seule, empreintes) et des droits limités.','Définir une rétention et sauvegarder les journaux.']),
  ('REG 25-3', 'Les journaux ne sont pas analysés par des outils automatiques ; leur exploitation est manuelle ou inexistante.', ARRAY['Anomalies noyées dans le volume de données.','Détection tardive des incidents.','Corrélation d''événements impossible.'], ARRAY['Déployer un outil d''analyse et de corrélation des journaux (SIEM ou équivalent).','Définir des règles et seuils d''alerte.','Traiter et tracer les alertes générées.']),
  ('REG 25-4', 'Les activités des administrateurs et opérateurs système ne sont pas journalisées, protégées ni revues régulièrement.', ARRAY['Perte d''imputabilité des actions privilégiées.','Abus interne non détecté.','Investigation post-incident impossible faute de traces.'], ARRAY['Activer la journalisation des actions des administrateurs et opérateurs.','Protéger les journaux contre l''altération.','Instaurer une revue périodique de ces journaux.']),
  ('REG 25-5', 'Aucun système de détection d''intrusions indépendant des administrateurs système et réseau ne contrôle la conformité de leurs activités.', ARRAY['Actions d''administration malveillantes ou erronées non détectées.','Absence de contrôle croisé sur les comptes privilégiés.','Intrusion durable sur le réseau non repérée.'], ARRAY['Déployer un IDS géré hors du périmètre des administrateurs contrôlés.','Définir les règles de détection des activités d''administration anormales.','Faire examiner les alertes par une fonction indépendante.']),
  ('REG 25-6', 'Les journaux ne sont pas vérifiés de façon permanente ; aucune surveillance continue n''est organisée.', ARRAY['Incident en cours non détecté pendant des semaines.','Réaction tardive aux comportements anormaux.','Traces utiles écrasées avant d''être lues.'], ARRAY['Organiser une surveillance continue ou des revues à fréquence définie.','Automatiser les alertes sur événements critiques.','Assigner clairement la responsabilité de la vérification.']),
  ('REG 25-7', 'Les événements majeurs ne sont pas tous enregistrés sur les ordinateurs et systèmes qui manipulent des données sensibles.', ARRAY['Accès illégitimes aux données sensibles sans trace.','Impossibilité d''établir l''étendue d''une fuite de données.','Absence de preuve en cas de litige.'], ARRAY['Lister les événements majeurs à enregistrer sur les systèmes sensibles.','Activer et vérifier cette journalisation sur chaque système concerné.','Définir une durée de conservation adaptée.']),
  ('REG 26-1', 'Les horloges des systèmes, ordinateurs et équipements réseau ne sont pas synchronisées sur un serveur de temps central.', ARRAY['Horodatages incohérents d''un équipement à l''autre.','Corrélation des journaux impossible lors d''une investigation.','Perte de valeur probante des traces.'], ARRAY['Déployer un serveur de temps central (NTP) de référence.','Configurer tous les systèmes et équipements pour s''y synchroniser.','Surveiller les dérives d''horloge.']),
  ('REG 26-2', 'Le serveur de temps n''est pas doublé d''un serveur de secours installé dans un lieu sécurisé.', ARRAY['Désynchronisation générale en cas de panne du serveur de temps.','Horodatages erronés pendant l''indisponibilité.','Défaillance des mécanismes dépendant du temps.'], ARRAY['Installer un serveur de temps de secours dans un lieu sécurisé.','Configurer les clients avec la source de secours.','Tester le basculement.']),
  ('REG 26-3', 'Les utilisateurs peuvent modifier la date, le fuseau horaire et les paramètres de synchronisation de l''horloge de leur poste.', ARRAY['Falsification des horodatages pour masquer des actions.','Dérive provoquant des échecs d''authentification.','Journaux inexploitables en cas d''investigation.'], ARRAY['Retirer aux utilisateurs le droit de modifier l''heure et la synchronisation.','Imposer ces paramètres par stratégie de groupe ou gestion centralisée.','Détecter les modifications d''horloge.']),
  ('REG 27-1', 'Les mises à jour des logiciels, applications et programmes en exploitation ne sont pas réalisées par des administrateurs qualifiés après autorisation du responsable de l''entité ou de l''AQSSI.', ARRAY['Mises à jour non autorisées ou mal exécutées.','Indisponibilité causée par des interventions non maîtrisées.','Absence de responsabilité identifiée.'], ARRAY['Réserver les mises à jour aux administrateurs qualifiés habilités.','Exiger une autorisation préalable du responsable ou de l''AQSSI.','Conserver la preuve de l''autorisation.']),
  ('REG 27-2', 'Les correctifs appliqués ne sont pas recommandés par les administrateurs système ou les éditeurs ; leur origine n''est pas maîtrisée.', ARRAY['Installation de correctifs non fiables ou malveillants.','Vulnérabilités connues non corrigées.','Incompatibilités provoquant des dysfonctionnements.'], ARRAY['Se baser uniquement sur les bulletins officiels des éditeurs.','Mettre en place une veille sur les vulnérabilités.','Valider l''origine et l''intégrité des correctifs avant déploiement.']),
  ('REG 27-3', 'Les correctifs ne sont pas appliqués d''abord sur un site de test, et les correctifs critiques ne sont pas traités en priorité haute avec installation immédiate.', ARRAY['Régressions découvertes en production.','Vulnérabilités critiques exploitables pendant des semaines.','Interruptions de service imprévues.'], ARRAY['Systématiser le test des correctifs sur un site de test avant la production.','Définir des délais d''installation pour les correctifs critiques.','Suivre le taux de correctifs critiques appliqués.']),
  ('REG 27-5', 'Aucune sauvegarde complète n''est effectuée avant l''application d''un correctif.', ARRAY['Impossibilité de revenir en arrière si le correctif échoue.','Perte de données ou de configuration lors de la mise à jour.','Indisponibilité prolongée du système.'], ARRAY['Rendre obligatoire une sauvegarde complète avant tout correctif.','Vérifier la validité de la sauvegarde avant d''intervenir.','Intégrer cette étape dans la procédure de changement.']),
  ('REG 27-7', 'Les ordinateurs connectés à internet ne sont pas configurés pour télécharger automatiquement les mises à jour recommandées, et les postes isolés ne sont pas mis à jour manuellement.', ARRAY['Postes exposés à des vulnérabilités connues.','Parc hétérogène en niveaux de correctifs.','Postes isolés jamais mis à jour.'], ARRAY['Activer le téléchargement automatique des mises à jour recommandées.','Planifier la mise à jour manuelle des postes isolés.','Contrôler le niveau de correctifs du parc.']),
  ('REG 27-8', 'Les mises à jour, mises à niveau et correctifs ne sont pas journalisés dans un registre par l''administrateur système.', ARRAY['Niveau de version réel des systèmes inconnu.','Investigation difficile après un incident lié à une mise à jour.','Impossibilité de prouver l''application des correctifs.'], ARRAY['Tenir un registre des mises à jour par système (date, version, intervenant).','Rapprocher le registre de l''état réel des systèmes.','Conserver le registre pour les audits.']),
  ('REG 27-9', 'Aucune procédure ne prévoit de rétablir les systèmes originaux à partir des sauvegardes lorsqu''une mise à jour ou un correctif affecte négativement les systèmes.', ARRAY['Systèmes laissés dégradés après une mise à jour défaillante.','Indisponibilité prolongée des services concernés.','Perte de données lors d''une récupération improvisée.'], ARRAY['Définir une procédure de retour arrière à partir des sauvegardes.','Tester périodiquement la restauration des systèmes.','Désigner les responsables de la décision de restauration.']),
  ('REG 28-1', 'Les opérations d''externalisation ne s''appuient pas sur une analyse de risques préalable ni sur une cible de sécurité servant de cadre au contrat avec le prestataire.', ARRAY['Prestataire sans obligations de sécurité adaptées.','Risques de dépendance et de fuite de données non évalués.'], ARRAY['Réaliser une analyse de risques avant toute externalisation.','Formaliser les objectifs de sécurité en cible de sécurité annexée au contrat.','Prévoir dans le contrat audits, notification d''incident et réversibilité.']),
  ('REG 28-2', 'Des données sensibles de l''Administration sont hébergées hors du territoire national sans accord du HFD ni dérogation motivée dans la décision d''homologation.', ARRAY['Soumission des données à une juridiction étrangère.','Perte de maîtrise et d''accès aux données sensibles.','Non-respect du principe de souveraineté numérique.'], ARRAY['Identifier la localisation de l''hébergement de toutes les données sensibles.','Rapatrier les données sur le territoire national ou obtenir l''accord du HFD et la dérogation formalisée.','Imposer la localisation des données dans les contrats d''hébergement.']),
  ('REG 28-3', 'Les utilisateurs ne sont pas sensibilisés aux risques liés au télétravail et à l''usage de terminaux mobiles dans les lieux publics, aéroports, hôtels et salles de conférence.', ARRAY['Observation d''écrans ou interception de communications en lieu public.','Perte ou vol d''équipements contenant des informations sensibles.'], ARRAY['Intégrer un module télétravail et mobilité au programme de sensibilisation.','Diffuser un guide des bonnes pratiques en déplacement.','Faire signer une charte de télétravail.']),
  ('REG 28-4', 'Les appareils mobiles ne sont pas physiquement protégés contre le vol en déplacement : absence de rangement sous clé et de dispositifs de verrouillage spéciaux.', ARRAY['Vol d''appareils contenant des informations sensibles.','Accès physique d''un tiers aux données de l''appareil.'], ARRAY['Fournir câbles antivol et dispositifs de rangement sécurisés.','Interdire de laisser les appareils sans surveillance (véhicule, chambre d''hôtel).','Définir la procédure de déclaration de perte ou de vol.']),
  ('REG 28-5', 'Aucune politique de contrôle d''accès, de protection anti-malware, de sauvegarde et de restriction d''installation d''applications non approuvées ne s''applique aux appareils mobiles.', ARRAY['Infection des appareils mobiles par des logiciels malveillants.','Perte de données non sauvegardées.','Applications non approuvées exfiltrant des données.'], ARRAY['Définir une politique de sécurité des appareils mobiles (verrouillage, authentification).','Déployer une solution de gestion des terminaux avec anti-malware et liste d''applications autorisées.','Organiser la sauvegarde des données professionnelles.']),
  ('REG 28-6', 'Les informations sensibles stockées et traitées sur les appareils mobiles ne sont pas protégées par des algorithmes de chiffrement labellisés par la Commission nationale de cryptologie.', ARRAY['Divulgation des données en cas de perte ou de vol.','Chiffrement non reconnu, donc non conforme.'], ARRAY['Activer le chiffrement intégral des appareils mobiles.','Utiliser des solutions et algorithmes labellisés par la Commission nationale de cryptologie.','Vérifier le chiffrement par contrôle de conformité des terminaux.']),
  ('REG 28-7', 'Les appareils mobiles de l''organisme ne sont pas restreints à un usage exclusivement professionnel, sans règle ni contrôle de l''usage personnel.', ARRAY['Installation d''applications personnelles introduisant des malwares.','Fuite de données par des usages privés.'], ARRAY['Interdire l''usage personnel dans la charte et la politique mobile.','Restreindre techniquement les installations et usages non professionnels.','Contrôler périodiquement la conformité d''usage.']),
  ('REG 28-8', 'Aucune règle n''interdit la connexion au réseau de l''organisme via des réseaux sans fil non sécurisés, et aucun contrôle technique ne l''empêche.', ARRAY['Interception des communications sur Wi-Fi public.','Attaque de l''homme du milieu sur la session de l''utilisateur.'], ARRAY['Imposer l''usage d''un VPN pour tout accès distant.','Interdire formellement les Wi-Fi non sécurisés dans la politique mobile.','Sensibiliser les utilisateurs à ce risque.']),
  ('REG 28-9', 'Aucun mécanisme d''effacement des données à distance n''est en place pour les appareils mobiles en cas de perte ou de vol.', ARRAY['Données sensibles accessibles à un tiers après perte.','Compromission irréversible faute de pouvoir neutraliser l''appareil.'], ARRAY['Déployer une solution de gestion des terminaux avec effacement à distance.','Définir une procédure de déclaration immédiate et d''effacement.','Tester périodiquement le mécanisme.']),
  ('REG 28-10', 'Les appareils mobiles ne sont pas contrôlés durant tout leur cycle de vie : inventaire, affectation, maintenance, restitution et mise au rebut ne sont pas suivis.', ARRAY['Appareils non inventoriés hors de tout contrôle.','Données résiduelles sur des appareils réaffectés ou mis au rebut.'], ARRAY['Tenir un inventaire des appareils mobiles avec affectation nominative.','Formaliser les étapes d''attribution, de maintenance, de restitution et d''effacement sécurisé.','Réaliser des revues périodiques de l''inventaire.']),
  ('REG 29-1', 'Aucune procédure formalisée de surveillance, de détection, d''analyse et de signalement des événements et incidents affectant les activités des réseaux n''est en place.', ARRAY['Incidents réseau non détectés ou détectés tardivement.','Réponse désorganisée aggravant l''impact.','Absence de remontée vers les organismes compétents.'], ARRAY['Définir et documenter une procédure de gestion des incidents (détection, qualification, réponse, clôture).','Mettre en place une surveillance des événements réseau (journaux, alertes).','Définir les critères et circuits de signalement.']),
  ('REG 29-2', 'Aucune structure d''alerte et de réaction rapide, composée de personnel qualifié et dotée d''un point focal interlocuteur des autres centres de gestion des incidents, n''est constituée au sein de l''entité.', ARRAY['Absence de responsable identifié lors d''un incident.','Délais de réaction excessifs.','Pas d''interlocuteur pour l''ADIE ou le STCC-SSI.'], ARRAY['Constituer une cellule de réponse aux incidents avec rôles et astreintes définis.','Désigner un point focal et communiquer ses coordonnées aux organismes compétents.','Former les membres de la cellule à la gestion d''incident.']),
  ('REG 29-3', 'Les incidents de sécurité ne sont pas systématiquement remontés ni signalés aux organismes compétents (ADIE, STCC-SSI, ARTP), et les actions de réponse ne sont pas coordonnées.', ARRAY['Incidents majeurs ignorés des autorités nationales.','Actions de traitement dispersées et contradictoires.','Non-respect des obligations de signalement.'], ARRAY['Définir les seuils et délais de signalement aux organismes nationaux compétents.','Formaliser un modèle de rapport d''incident et un circuit de coordination.','Tenir la trace de chaque signalement émis.']),
  ('REG 29-4', 'Les moyens de traitement de l''information critiques ne disposent pas de redondance (serveurs, liaisons, alimentation) garantissant leur disponibilité.', ARRAY['Interruption de service par panne d''un composant unique.','Indisponibilité prolongée des services critiques.'], ARRAY['Identifier les composants critiques et leurs points de défaillance uniques.','Mettre en place la redondance adaptée (liaisons, serveurs, alimentation, stockage).','Tester périodiquement les bascules.']),
  ('REG 29-5', 'Le plan de continuité d''activité n''est pas revu régulièrement et ne reflète pas les changements intervenus dans le système d''information.', ARRAY['Plan obsolète inapplicable lors d''un sinistre.','Reprise d''activité plus longue que prévu.'], ARRAY['Planifier une revue annuelle du PCA et après tout changement majeur du SI.','Maintenir à jour contacts, inventaires et procédures de reprise.','Tracer les révisions et validations par la direction.']),
  ('REG 29-6', 'Le plan de continuité d''activité n''est pas testé périodiquement et sa fiabilité n''est pas démontrée.', ARRAY['Défaillances du plan découvertes lors d''un sinistre réel.','Objectifs de reprise (RTO/RPO) non tenus.'], ARRAY['Planifier des tests périodiques (exercices sur table, bascule technique).','Documenter les résultats et corriger les écarts constatés.','Faire valider les résultats par la direction.']),
  ('REG 29-7', 'Les utilisateurs ne sont pas formés aux actions à mener en cas de violation de la politique de sécurité.', ARRAY['Réactions inadaptées aggravant l''incident (suppression de preuves, retard de signalement).','Violations non traitées faute de savoir qui alerter.'], ARRAY['Inclure dans la sensibilisation les conduites à tenir en cas de violation.','Diffuser une fiche réflexe indiquant le contact à alerter.','Vérifier l''acquisition par des tests ou exercices.']),
  ('REG 29-8', 'Les utilisateurs ne sont pas formés à détecter les actions suspectes ou anormales (dysfonctionnements, comportements inhabituels du système) pouvant présager un incident.', ARRAY['Signaux précurseurs d''attaque ignorés par les utilisateurs.','Compromission prolongée non signalée.'], ARRAY['Former les utilisateurs aux indices d''incident (lenteurs, messages inhabituels, fichiers modifiés).','Réaliser des campagnes de simulation d''hameçonnage.','Rappeler le canal de signalement.']),
  ('REG 29-9', 'La procédure de réponse aux incidents ne comprend pas de phase de recueil et d''analyse des preuves, de communication détaillée sur l''incident ni de description de la méthode de traitement.', ARRAY['Traitement non reproductible, causes racines non identifiées.','Perte d''éléments probants utiles à une action en justice.','Communication improvisée vers les parties prenantes.'], ARRAY['Compléter la procédure par les phases de recueil des preuves, d''analyse et de communication.','Documenter chaque incident (chronologie, méthode de traitement, résultat).','Définir les modèles de communication interne et externe.']),
  ('REG 29-10', 'La procédure de recueil des preuves numériques ne prend pas en compte la chaîne de traçabilité, les aptitudes du personnel, les responsabilités ni la documentation, et la norme ISO/CEI 27037 n''est pas appliquée.', ARRAY['Preuves numériques altérées ou irrecevables devant une juridiction.','Impossibilité d''établir l''origine d''une intrusion.'], ARRAY['Rédiger une procédure de collecte de preuves conforme à l''ISO/CEI 27037 avec chaîne de traçabilité.','Former le personnel concerné ou contractualiser un prestataire d''investigation.','Documenter chaque collecte (horodatage, intervenant, support).']),
  ('REG 29-11', 'Aucune typologie des incidents de sécurité n''est définie et les enseignements des incidents survenus ne sont pas capitalisés.', ARRAY['Incidents récurrents sans traitement des causes.','Impossibilité de prioriser les risques et de produire des statistiques.'], ARRAY['Définir une typologie et des niveaux de gravité des incidents.','Tenir un registre des incidents avec analyse post-incident.','Intégrer les enseignements au plan d''actions SSI.']),
  ('REG 30-1', 'Les audits de sécurité ne sont pas réalisés régulièrement pour vérifier l''atteinte des objectifs et la conformité aux normes, ou leurs rapports ne sont pas transmis à la Commission nationale de cryptologie.', ARRAY['Écarts de conformité non détectés dans la durée.','Non-respect de l''obligation de transmission à la Commission.'], ARRAY['Établir un programme d''audit périodique couvrant le périmètre de la PSSI-ES.','Transmettre systématiquement les rapports à la Commission nationale de cryptologie.']),
  ('REG 30-2', 'La compétence des auditeurs des SI de l''entité n''est ni évaluée ni démontrée : absence de qualification, formation ou expérience documentée.', ARRAY['Audits peu fiables, écarts non détectés.','Recommandations inadaptées au contexte.'], ARRAY['Définir des critères de compétence des auditeurs et les vérifier.','Prévoir une formation continue ou recourir à des auditeurs qualifiés.']),
  ('REG 30-3', 'Les rapports d''audit ne sont pas systématiquement adressés au HFD avec des recommandations, ni communiqués à la Commission nationale de cryptologie, et aucune suite n''est donnée aux violations de procédures.', ARRAY['Autorités non informées des anomalies constatées.','Violations de procédures sans sanction.'], ARRAY['Formaliser la chaîne de diffusion Auditeur → HFD → Commission.','Joindre des recommandations et suivre les sanctions éventuelles.']),
  ('REG 30-4', 'Les structures auditées n''appliquent pas toutes les mesures proposées et ne produisent pas de rapports de conformité.', ARRAY['Anomalies d''audit persistantes d''un cycle à l''autre.','Absence de preuve de remédiation.'], ARRAY['Établir un plan d''actions avec responsables et échéances.','Exiger un rapport de conformité à la clôture des actions.']),
  ('REG 30-5', 'Le respect des lois sur la cryptologie (2008-41), les données personnelles (2008-12), la propriété intellectuelle et la cybersécurité n''est ni suivi ni démontré : aucune veille ni revue de conformité n''est menée.', ARRAY['Sanctions pour non-conformité légale.','Usage de moyens de cryptologie hors cadre autorisé.'], ARRAY['Établir un registre des exigences légales applicables.','Réaliser une revue de conformité légale annuelle.']),
  ('REG 30-6', 'Les normes de sécurité publiées par la Commission nationale de cryptologie ne sont pas suivies par l''entité : leurs mises à jour ne sont pas intégrées aux référentiels internes.', ARRAY['Application de normes obsolètes.','Écarts de conformité avec les exigences en vigueur.'], ARRAY['Mettre en place une veille sur les normes de la Commission.','Intégrer les mises à jour dans les politiques et procédures internes.']),
  ('REG 30-7', 'Les rapports communiqués aux autorités compétentes sont incomplets ou non exploités : le retour d''expérience n''alimente pas la planification des projets futurs.', ARRAY['Mêmes défaillances reproduites dans les futurs projets.','Décisions des autorités fondées sur des informations partielles.'], ARRAY['Standardiser un modèle de rapport complet pour les autorités.','Intégrer le retour d''expérience dans la planification des projets.'])
) as t(code, descr, risks, recos)
join public.controls c on c.code = t.code
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000017')
where not exists (
  select 1 from public.finding_templates ft
  where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'minor_nc'
);

-- (2) Constats-types personnalisés — NC majeure (contrôles critiques).
insert into public.finding_templates (scope, control_id, classification, description, risks, recommendations)
select 'platform', c.id, 'major_nc', t.descr, t.risks, t.recos
from (values
  ('REG 7-1', 'Aucune politique de sécurité applicable aux fournisseurs n''est définie : les prestations externalisées ne sont encadrées par aucune exigence de sécurité.', ARRAY['Accès de prestataires non maîtrisé aux systèmes et données de l''organisme.','Propagation d''une compromission via la chaîne de sous-traitance.','Absence de recours contractuel en cas d''incident imputable au fournisseur.'], ARRAY['Définir une politique de sécurité fournisseurs et l''imposer contractuellement.','Qualifier les fournisseurs selon leur niveau d''accès et les auditer.','Encadrer les accès des prestataires (moindre privilège, traçabilité, révocation).']),
  ('REG 7-2', 'Aucune procédure ne permet de surveiller la conformité des fournisseurs aux exigences de sécurité de l''information : aucun contrôle n''est réalisé après la signature des contrats.', ARRAY['Non-respect des exigences de sécurité par les fournisseurs sans détection.','Incidents d''origine fournisseur découverts uniquement après impact.','Aucune base factuelle pour actionner les pénalités ou la résiliation.'], ARRAY['Mettre en place sans délai une procédure de surveillance pour les fournisseurs critiques.','Exiger des fournisseurs des rapports et attestations périodiques de conformité.','Désigner un responsable du suivi de chaque fournisseur.']),
  ('REG 7-3', 'Aucun programme de sensibilisation n''est mis en place pour le personnel en contact avec les fournisseurs : les règles de sécurité applicables et les niveaux d''accès aux SI ne leur sont pas communiqués.', ARRAY['Octroi d''accès excessifs aux prestataires par méconnaissance des règles.','Fuite d''informations lors des échanges avec les fournisseurs.','Ingénierie sociale facilitée via la relation fournisseur.'], ARRAY['Élaborer et déployer immédiatement un programme de sensibilisation ciblé.','Remettre aux interlocuteurs fournisseurs un guide des règles et des niveaux d''accès.','Rendre la sensibilisation obligatoire avant toute relation avec un fournisseur.']),
  ('REG 7-4', 'Aucune charte de sécurité n''est signée par les fournisseurs : ceux-ci ne s''engagent formellement à respecter aucune clause de sécurité.', ARRAY['Absence d''engagement opposable du fournisseur en cas d''incident.','Pratiques de sécurité laissées à la discrétion de chaque prestataire.','Responsabilité de l''organisme engagée sans recours contre le fournisseur.'], ARRAY['Rédiger une charte de sécurité fournisseur et la faire signer à tous les fournisseurs en priorité.','Conditionner l''accès aux SI à la signature de la charte.','Intégrer la charte aux contrats et à leurs renouvellements.']),
  ('REG 7-5', 'Les fournisseurs ne reçoivent aucun rappel des exigences légales sur la protection des données à caractère personnel, les droits d''auteur et la propriété intellectuelle, et leur respect n''est pas contrôlé.', ARRAY['Violation de la loi 2008-12 par un sous-traitant, engageant la responsabilité de l''organisme.','Litiges de propriété intellectuelle sur les livrables.','Sanctions de la Commission de protection des données personnelles.'], ARRAY['Insérer sans délai des clauses légales dans tous les contrats fournisseurs.','Faire signer des engagements de confidentialité et de conformité à la loi 2008-12.','Contrôler le respect de ces clauses lors des revues fournisseurs.']),
  ('REG 7-6', 'Aucun point focal n''est désigné pour traiter les questions de sécurité avec les fournisseurs : les échanges ne sont pas centralisés.', ARRAY['Incidents fournisseurs non signalés ou traités sans coordination.','Absence de responsable de la relation sécurité avec les prestataires.','Informations de sécurité contradictoires transmises aux fournisseurs.'], ARRAY['Nommer immédiatement un point focal sécurité fournisseurs.','Mettre en place un canal dédié de signalement et d''échange.','Intégrer le point focal aux contrats comme interlocuteur officiel.']),
  ('REG 7-7', 'Les sous-traitants travaillant pour le compte des fournisseurs ne sont ni identifiés ni pris en compte : seuls les fournisseurs directs sont visés par les exigences de sécurité.', ARRAY['Accès aux données par des intervenants inconnus de l''organisme.','Compromission via un sous-traitant échappant à tout contrôle.','Impossibilité d''attribuer la responsabilité en cas d''incident.'], ARRAY['Imposer contractuellement aux fournisseurs la déclaration de leurs sous-traitants.','Répercuter les exigences de sécurité de l''organisme sur toute la chaîne de sous-traitance.','Interdire toute sous-traitance sans accord écrit préalable.']),
  ('REG 7-8', 'Les contrats avec les fournisseurs n''intègrent aucune clause sur la chaîne d''approvisionnement informatique : ni conformité aux normes de sécurité des produits, ni publication ou preuve des exigences de sécurité satisfaites.', ARRAY['Introduction de matériels ou logiciels vulnérables ou compromis.','Attaque par la chaîne d''approvisionnement sans recours contractuel.','Impossibilité d''exiger la preuve de sécurité des produits livrés.'], ARRAY['Intégrer sans délai des clauses de sécurité de la chaîne d''approvisionnement dans les contrats.','Exiger la publication et la preuve des exigences de sécurité satisfaites par les produits.','Évaluer la sécurité des produits avant leur mise en production.']),
  ('REG 7-9', 'Aucune procédure d''audit n''est en place pour les prestations des fournisseurs : ni la sécurité ni la qualité des services rendus ne sont vérifiées.', ARRAY['Fournisseurs non conformes sans détection durant toute la durée du contrat.','Prestations dégradées ou non sécurisées sans levier correctif.','Absence de droit d''audit exploitable en cas d''incident.'], ARRAY['Instaurer sans délai des audits des fournisseurs critiques.','Prévoir contractuellement un droit d''audit sur les fournisseurs.','Suivre les écarts constatés jusqu''à leur correction.']),
  ('REG 8-1', 'Aucune zone sécurisée n''a été définie ni identifiée : les salles serveurs, centres de données et locaux réseau sont traités comme des locaux ordinaires.', ARRAY['Absence de périmètre physique de sécurité autour des équipements critiques du SI.','Accès libre aux salles serveurs et de commutation par tout occupant des locaux.','Impossibilité d''appliquer toute mesure de protection physique faute de zones définies.'], ARRAY['Recenser sans délai les locaux hébergeant des moyens de traitement de l''information et les classer en zones sécurisées.','Formaliser le périmètre de chaque zone dans un document approuvé et affecter un responsable.','Déployer un balisage et des restrictions d''accès adaptés à chaque zone.']),
  ('REG 8-2', 'Aucun badge ni autorisation écrite n''est exigé pour pénétrer dans les zones sécurisées : l''accès n''est soumis à aucune validation du responsable désigné.', ARRAY['Intrusion physique directe dans les salles serveurs et locaux sensibles.','Vol, sabotage ou altération des équipements sans possibilité d''imputer l''acte.','Atteinte à la disponibilité des services critiques hébergés.'], ARRAY['Mettre en place sans délai un contrôle d''accès nominatif par badge ou autorisation écrite pour chaque zone sécurisée.','Désigner un responsable de la délivrance et restreindre les accès au strict besoin.','Installer une journalisation des entrées et un dispositif de détection d''intrusion.']),
  ('REG 8-3', 'Aucun registre d''accès n''est tenu à l''entrée des zones sécurisées : les entrées et sorties des personnes ne sont ni identifiées ni horodatées.', ARRAY['Aucune imputabilité possible en cas de vol, sabotage ou fuite d''information.','Présence de personnes non identifiées dans les zones sensibles sans détection.','Absence totale de preuve pour les enquêtes et les audits.'], ARRAY['Instaurer immédiatement un registre d''accès à chaque zone sécurisée (identité, but, signature, heures).','Désigner un responsable chargé de vérifier quotidiennement la complétude du registre.','Étudier un système électronique de journalisation des accès en complément.']),
  ('REG 8-4', 'Aucun agent de sécurité n''est affecté à l''entrée des sites sensibles : l''accès, les bagages et les alarmes ne font l''objet d''aucune surveillance humaine.', ARRAY['Entrée libre de personnes non autorisées sur les sites sensibles.','Introduction d''objets dangereux ou sortie de matériels sans contrôle.','Alarmes et appels d''urgence sans réponse, aggravant tout sinistre.'], ARRAY['Affecter sans délai un agent de sécurité à l''entrée de chaque site sensible.','Définir par écrit ses missions : refus d''accès, registre, fouille des bagages, gestion des alarmes.','Former l''agent aux procédures d''urgence et contrôler régulièrement sa prestation.']),
  ('REG 8-5', 'Les zones sécurisées ne sont pas fermées en dehors des heures de service : portes et fenêtres restent accessibles et les conduits ne sont pas protégés par des grilles.', ARRAY['Intrusion nocturne facilitée jusque dans les salles serveurs.','Vol ou destruction d''équipements sans aucune barrière physique.','Interruption prolongée de services critiques suite à un sabotage.'], ARRAY['Instaurer sans délai la fermeture et le verrouillage systématiques des zones sécurisées hors service.','Poser des grilles métalliques sur tous les conduits et sécuriser les fenêtres et issues de secours.','Contrôler quotidiennement la fermeture et consigner les vérifications.']),
  ('REG 8-6', 'Aucune procédure de révocation des droits d''accès physiques n''existe : les badges et autorisations des agents partis, mutés ou suspendus restent valides.', ARRAY['Accès durable de personnes ayant quitté l''organisme aux zones sécurisées.','Risque de malveillance interne par un agent suspendu ou en conflit.','Aucune maîtrise du nombre réel de détenteurs d''accès.'], ARRAY['Mettre en place immédiatement une procédure de révocation instantanée des accès à chaque événement RH.','Auditer et désactiver tous les badges de personnes ne devant plus avoir accès.','Imposer la restitution du badge et son enregistrement lors du départ.']),
  ('REG 8-7', 'Les enregistrements d''accès (registres, journaux de badge, vidéo) ne sont ni sauvegardés ni conservés : aucune période de conservation n''est fixée.', ARRAY['Aucune preuve d''accès disponible après un incident ou un vol.','Impossibilité de répondre à une enquête interne ou judiciaire.','Perte définitive des journaux en cas de défaillance du support.'], ARRAY['Mettre en place immédiatement la sauvegarde régulière de tous les enregistrements d''accès.','Fixer et appliquer une durée de conservation adaptée aux exigences légales.','Stocker les sauvegardes dans un lieu distinct et protégé.']),
  ('REG 8-8', 'Aucune évaluation de risque physique ni analyse coûts-avantages n''a été réalisée : les équipements de sécurité sont choisis sans fondement.', ARRAY['Contre-mesures inadaptées aux menaces réelles des sites.','Dépenses de sécurité inefficaces et lacunes critiques non identifiées.','Absence de justification devant les autorités ou lors d''un audit.'], ARRAY['Réaliser en priorité une évaluation de risque physique sur chaque site sensible.','Sélectionner les équipements sur la base de ses résultats et d''une analyse coûts-avantages.','Faire valider les choix par la direction et les réviser périodiquement.']),
  ('REG 11-1', 'Le personnel n''est ni informé de l''existence des zones sécurisées ni du principe du besoin d''en connaître : l''accès n''est pas limité par la justification métier.', ARRAY['Accès généralisé du personnel aux zones sensibles.','Aucun levier de sanction ou de contrôle faute de règle connue.','Multiplication des risques d''erreur ou de malveillance interne.'], ARRAY['Diffuser sans délai une note d''information sur les zones sécurisées et le besoin d''en connaître.','Intégrer ces règles dans la sensibilisation obligatoire et l''accueil des nouveaux agents.','Réviser les droits d''accès existants selon ce principe.']),
  ('REG 11-2', 'Aucune règle n''interdit le travail sans surveillance dans les zones sécurisées : prestataires et agents y opèrent seuls et sans contrôle de manière habituelle.', ARRAY['Sabotage, vol ou installation de dispositifs malveillants sans témoin.','Modification non contrôlée d''équipements critiques.','Aucune détection d''un sinistre ou d''une intrusion.'], ARRAY['Interdire formellement le travail seul et sans surveillance en zone sécurisée.','Imposer l''accompagnement des prestataires par un agent habilité.','Contrôler le respect de la règle par des rondes et la revue des registres.']),
  ('REG 11-3', 'Les zones sécurisées inoccupées restent ouvertes et ne font l''objet d''aucun contrôle périodique.', ARRAY['Accès libre aux équipements critiques lorsque la zone est vide.','Vol ou altération non détectés pendant les périodes d''inoccupation.','Retard de détection de toute anomalie physique.'], ARRAY['Mettre en oeuvre sans délai le verrouillage systématique des zones inoccupées.','Instaurer des rondes régulières avec registre de contrôle.','Désigner un responsable de la vérification de la fermeture.']),
  ('REG 11-4', 'Aucune interdiction des équipements photo, vidéo, audio ou des appareils mobiles à caméra n''est instaurée dans les zones sécurisées.', ARRAY['Captation libre d''images et de sons de l''infrastructure critique.','Divulgation d''informations sensibles (écrans, plans, configurations).','Aucun moyen de sanction ou de contrôle des enregistrements.'], ARRAY['Interdire formellement les dispositifs de captation en zone sécurisée, sauf autorisation écrite.','Mettre en place des casiers de dépôt des appareils à l''entrée.','Intégrer cette règle au règlement intérieur et à la sensibilisation.']),
  ('REG 12-1', 'Aucune zone d''approvisionnement n''est désignée : les livraisons pénètrent librement dans les locaux, sans restriction d''accès.', ARRAY['Les livreurs accèdent aux locaux internes et sensibles.','Introduction de matières ou dispositifs malveillants sans contrôle.','Vol de matériels livrés sans traçabilité.'], ARRAY['Désigner immédiatement une zone d''approvisionnement distincte et à accès restreint.','Interdire aux livreurs l''accès au-delà de cette zone sans accompagnement.','Contrôler et consigner chaque livraison à l''arrivée.']),
  ('REG 12-2', 'Aucune inspection des matières entrantes n''est réalisée : les livraisons pénètrent sur le site sans contrôle de substances explosives, chimiques ou autres.', ARRAY['Introduction d''engins ou substances dangereuses dans des sites sensibles.','Atteinte à la sécurité des personnes et destruction d''infrastructures.','Responsabilité engagée en cas d''incident évitable.'], ARRAY['Instaurer sans délai l''inspection de toutes les matières entrantes dans la zone de livraison.','Acquérir les équipements de détection appropriés et former les agents.','Interdire toute sortie de la zone avant validation du contrôle.']),
  ('REG 12-3', 'Aucun enregistrement des matières entrantes n''est effectué à leur arrivée : les matériels livrés ne sont pas intégrés au processus d''enregistrement des actifs.', ARRAY['Disparition ou détournement de matériels sans trace.','Inventaire des actifs durablement faux et incomplet.','Impossibilité de prouver la réception ou le vol d''un équipement.'], ARRAY['Mettre en place immédiatement l''enregistrement de toute matière dès son arrivée.','Désigner un responsable de la réception et du renseignement de l''inventaire.','Régulariser par un inventaire physique des matériels déjà reçus.']),
  ('REG 12-4', 'Aucune comptabilité matière n''est tenue par les directions chargées des équipements dans les différentes entités.', ARRAY['Aucun suivi des équipements acquis, déplacés ou mis au rebut.','Pertes et détournements de matériels non détectés.','Perte de maîtrise du patrimoine technique de l''organisme.'], ARRAY['Instaurer sans délai la comptabilité matière dans chaque entité sous la responsabilité de la direction des équipements.','Réaliser un inventaire physique général pour établir la situation de départ.','Mettre en place des contrôles périodiques de cohérence.']),
  ('REG 13-1', 'Les installations sensibles ne sont équipées d''aucun système d''alarme ou celui-ci n''est jamais contrôlé et reste hors service.', ARRAY['Intrusion ou sinistre non détectés dans les installations sensibles.','Retard d''intervention aggravant les dégâts et pertes de données.','Aucune dissuasion contre les actes malveillants.'], ARRAY['Installer sans délai un système d''alarme dans chaque installation sensible.','Établir un programme de contrôle et de test périodique documenté.','Relier les alarmes à une surveillance permanente capable d''intervenir.']),
  ('REG 13-2', 'Le matériel est installé dans des locaux non sécurisés dont les portes et fenêtres donnent directement accès aux équipements depuis l''extérieur ; aucune issue de secours n''est prévue.', ARRAY['Intrusion ou raccordement de dispositifs malveillants depuis l''extérieur.','Vol ou destruction du matériel sans effraction complexe.','Danger pour les personnes faute d''issue de secours.'], ARRAY['Déplacer sans délai les équipements vers des salles sécurisées.','Renforcer ou supprimer tout accès par portes et fenêtres vers le matériel.','Aménager des issues de secours conformes dans tous les sites.']),
  ('REG 13-3', 'Les sites sensibles ne sont équipés d''aucun dispositif de détection ni de lutte contre l''incendie (détecteurs de fumée, extincteurs).', ARRAY['Incendie non détecté détruisant équipements et données.','Perte totale de disponibilité des services hébergés.','Mise en danger des personnes présentes.'], ARRAY['Installer en urgence détecteurs de fumée et extincteurs adaptés dans tous les sites sensibles.','Mettre en place un programme de contrôle et de test réguliers.','Former le personnel à l''usage des extincteurs et à l''évacuation.']),
  ('REG 13-4', 'Les sites sensibles ne sont pas construits en matériaux réfractaires et contiennent de nombreux matériels inflammables (meubles en bois, rideaux, tapis).', ARRAY['Embrasement rapide de la salle à partir d''un simple court-circuit.','Destruction complète des équipements et des données sur place.','Interruption durable des services critiques.'], ARRAY['Évacuer immédiatement tout matériel inflammable des sites sensibles.','Programmer la mise aux normes de la construction avec des matériaux réfractaires.','Faire valider la conformité par un organisme compétent.']),
  ('REG 13-5', 'Les installations électriques des sites sensibles ne sont pas conformes aux spécifications des fabricants ni aux normes de sécurité électrique : câblage précaire et protections absentes.', ARRAY['Risque élevé d''incendie d''origine électrique.','Détérioration des équipements par surtension ou mauvaise alimentation.','Arrêt brutal des services critiques.'], ARRAY['Faire réaliser sans délai un diagnostic par un électricien qualifié.','Corriger en priorité toutes les non-conformités relevées.','Faire certifier la conformité de l''installation après travaux.']),
  ('REG 13-6', 'Aucune inspection ni aucun test des installations électriques (éclairage, câbles, générateur de secours) n''est jamais réalisé.', ARRAY['Défaillances électriques latentes pouvant provoquer incendie ou panne générale.','Générateur de secours non fonctionnel au moment critique.','Absence de preuve de maintenance en cas de sinistre.'], ARRAY['Faire inspecter sans délai l''ensemble des installations électriques par un prestataire qualifié.','Mettre en place un programme de maintenance et de test périodique.','Tester le générateur en charge et documenter les essais.']),
  ('REG 13-7', 'Aucun générateur de secours ne garantit l''alimentation électrique d''urgence des installations sensibles.', ARRAY['Arrêt total des services lors de toute coupure du réseau électrique.','Corruption de données et dommages aux équipements par arrêt brutal.','Indisponibilité prolongée sans solution de continuité.'], ARRAY['Acquérir et installer en priorité un générateur de secours dimensionné pour les charges critiques.','Prévoir un basculement automatique et un approvisionnement en carburant sécurisé.','Tester régulièrement le dispositif en situation réelle.']),
  ('REG 13-8', 'Les équipements sensibles ne disposent d''aucune alimentation électrique permanente : aucun onduleur ni dispositif de continuité n''est installé.', ARRAY['Arrêt immédiat des équipements à chaque micro-coupure du secteur.','Perte de données et dommages matériels sur serveurs et réseau.','Indisponibilité fréquente des services critiques.'], ARRAY['Installer sans délai des onduleurs sur tous les équipements sensibles.','Prévoir une alimentation redondante (double source) pour les équipements critiques.','Superviser en continu l''alimentation électrique et alerter en cas d''anomalie.']),
  ('REG 13-9', 'Les équipements des sites sensibles sont posés à même le sol et aucun système de détection de fuite d''eau n''est installé.', ARRAY['Destruction de serveurs et d''équipements réseau en cas d''inondation ou de fuite de canalisation.','Interruption prolongée de services critiques sans alerte préalable.','Perte de données non sauvegardées stockées sur les matériels noyés.'], ARRAY['Surélever sans délai tous les équipements sensibles sur des supports adaptés.','Déployer des capteurs de fuite d''eau reliés à une alarme dans chaque site sensible.','Faire contrôler les canalisations et évacuations situées à proximité des salles techniques.']),
  ('REG 13-10', 'Aucun dispositif maîtrisé de climatisation, de ventilation ou d''évacuation des eaux usées n''est entretenu dans les locaux techniques, et aucun appareil de mesure de température ou d''humidité n''est installé.', ARRAY['Surchauffe et arrêt des serveurs et équipements réseau.','Corrosion et condensation endommageant les matériels en environnement humide.','Interruption durable des activités de l''entité sans signe avant-coureur.'], ARRAY['Équiper sans délai les salles techniques d''une climatisation dimensionnée et redondante.','Poser des sondes de température et d''humidité avec alertes en temps réel.','Mettre en place un contrat et un calendrier de vérification des installations.']),
  ('REG 13-11', 'Aucun site de reprise sur sinistre ni site de stockage de données distant n''existe ; les données et les moyens de secours sont hébergés sur le site principal.', ARRAY['Perte définitive des données en cas d''incendie, d''inondation ou de destruction du site principal.','Impossibilité de reprendre l''activité après un sinistre majeur.','Rupture prolongée de services essentiels de l''entité.'], ARRAY['Définir et mettre en place un site de reprise très éloigné du site principal.','Répliquer ou sauvegarder les données critiques sur ce site distant.','Tester périodiquement la bascule vers le site de secours.']),
  ('REG 13-12', 'Les matériels, supports de stockage défectueux et pièces de rechange mis au rebut sont entreposés dans des locaux ouverts, sans pièce séparée ni verrouillage.', ARRAY['Récupération de données sensibles sur des disques ou supports jetés sans contrôle.','Vol ou détournement de matériels sans traçabilité.','Fuite d''informations classifiées via des supports défectueux.'], ARRAY['Aménager sans délai une pièce séparée et verrouillée pour les matériels hors service.','Appliquer une procédure de destruction sécurisée des supports avant évacuation.','Enregistrer chaque entrée et sortie de la pièce.']),
  ('REG 13-13', 'La salle d''équipements et les racks affichent ouvertement les noms, fonctions, schémas réseau, numéros de ports et adresses IP des équipements.', ARRAY['Ciblage direct des équipements les plus critiques par une personne malveillante présente sur site.','Cartographie complète du réseau obtenue sans effort, facilitant une attaque logique.','Sabotage ou erreurs d''intervention par des tiers identifiant les équipements.'], ARRAY['Retirer immédiatement tout affichage décrivant noms, buts, schémas, ports et adresses IP.','Adopter un repérage neutre et conserver la documentation dans un espace à accès restreint.','Contrôler périodiquement l''absence d''affichage dans les salles sensibles.']),
  ('REG 13-14', 'Aucun nettoyage des équipements n''est effectué : la poussière s''accumule sur les matériels, ventilateurs et grilles des salles techniques.', ARRAY['Pannes en série et arrêts de serveurs par surchauffe.','Risque d''incendie dû à l''accumulation de poussière sur les équipements électriques.','Réduction de la durée de vie des matériels et coûts de remplacement imprévus.'], ARRAY['Procéder immédiatement à un nettoyage complet des équipements et salles techniques.','Définir une fréquence de nettoyage et en confier la responsabilité à une équipe identifiée.','Contrôler les filtres et ventilations lors de chaque campagne.']),
  ('REG 13-15', 'Les salles abritant des équipements sensibles servent librement à d''autres activités (travail de bureau, stockage, réunions) sans aucune interdiction ni contrôle.', ARRAY['Interruption de service par débranchement ou choc accidentel d''équipements.','Accès incontrôlé de multiples personnes à des équipements critiques.','Incendie ou dégradation liés à des matériaux ou usages étrangers à la salle.'], ARRAY['Interdire formellement et sans délai toute activité autre que celles prévues dans ces salles.','Évacuer le mobilier et les stocks étrangers aux équipements.','Contrôler régulièrement le respect de la règle.']),
  ('REG 13-16', 'Aucune interdiction de manger, boire ou fumer n''existe dans la zone sécurisée ; ces pratiques y sont courantes.', ARRAY['Court-circuit et destruction de matériels par projection de liquides.','Risque d''incendie dans une zone abritant des équipements critiques.','Encrassement des équipements par cendres et miettes.'], ARRAY['Instaurer immédiatement une interdiction stricte de manger, boire et fumer dans la zone sécurisée.','Aménager un espace dédié hors zone sécurisée pour ces usages.','Contrôler et sanctionner les infractions.']),
  ('REG 14-1', 'Toutes les lignes électriques et de télécommunication alimentant les systèmes d''information sont aériennes ou apparentes, sans aucun enfouissement alors qu''il est réalisable.', ARRAY['Coupures d''alimentation et de connectivité fréquentes lors d''intempéries ou d''accidents.','Sabotage ou vol de câbles sans difficulté.','Interruption prolongée des services critiques.'], ARRAY['Planifier l''enfouissement des lignes électriques et de télécommunication dans la mesure du possible.','Mettre en place une protection physique provisoire des lignes exposées.','Prévoir un chemin de secours pour la connectivité et l''alimentation.']),
  ('REG 14-2', 'Les câbles électriques et de télécommunication cheminent ensemble, en faisceaux communs, sans aucune séparation.', ARRAY['Perturbations réseau permanentes et pertes de paquets dues aux interférences.','Risque de dégradation des câbles de télécommunication lors d''intervention sur l''électricité.','Pannes intermittentes difficiles à localiser.'], ARRAY['Reprendre le câblage pour séparer les câbles électriques et de télécommunication.','Prévoir des chemins de câbles distincts dans les nouvelles installations.','Documenter le plan de câblage après remise en conformité.']),
  ('REG 14-3', 'Les câbles de télécommunication sont posés à nu, dégradés ou non protégés, sans conduits ni câbles redondants.', ARRAY['Coupure de service à la moindre détérioration d''un câble sans solution de repli.','Accès facilité aux câbles pour écoute ou sabotage.','Reprise lente des services après incident faute de liaison de secours.'], ARRAY['Remplacer les câbles défaillants par des câbles fiables placés en conduits.','Installer des liaisons redondantes pour les services essentiels.','Tester le basculement sur les liaisons de secours.']),
  ('REG 14-4', 'Les câbles électriques alimentant les équipements sont posés au sol ou à nu, sans aucun conduit approprié.', ARRAY['Court-circuit ou incendie lié à des câbles endommagés.','Électrisation du personnel ou des intervenants.','Coupure d''alimentation de matériels critiques.'], ARRAY['Placer sans délai tous les câbles électriques dans des conduits appropriés.','Faire vérifier l''installation électrique par un professionnel habilité.','Interdire la pose de câbles apparents au sol.']),
  ('REG 14-5', 'Les panneaux de brassage et les salles de câblage sont situés dans ou à proximité immédiate des zones d''accueil du public, sans isolement ni contrôle d''accès.', ARRAY['Branchement d''un équipement pirate sur le réseau par un visiteur.','Débranchement volontaire entraînant une coupure réseau.','Interception du trafic via des connexions directes sur les panneaux.'], ARRAY['Isoler immédiatement les panneaux dans des armoires ou locaux fermés à clé.','Mettre en place un contrôle d''accès restreint au personnel autorisé.','Déplacer ces équipements hors des zones accessibles au public.']),
  ('REG 14-6', 'Les panneaux de répartition électrique et les chambres de câblage sont accessibles à tous, sans verrouillage ni limitation au personnel autorisé.', ARRAY['Coupure volontaire ou accidentelle de l''alimentation des équipements critiques.','Sabotage de l''alimentation sans traçabilité.','Danger d''électrisation pour des personnes non habilitées.'], ARRAY['Verrouiller sans délai les panneaux électriques et chambres de câblage.','Restreindre l''accès au seul personnel habilité, avec contrôle strict.','Mettre en place un registre ou une journalisation des accès.']),
  ('REG 14-7', 'Aucun paratonnerre ni parafoudre n''équipe les sites sensibles.', ARRAY['Destruction d''équipements informatiques et télécoms par surtension lors d''un impact de foudre.','Dommages au bâtiment et risque d''incendie lors d''un orage.','Interruption durable des services faute de matériels de remplacement.'], ARRAY['Installer des paratonnerres sur les bâtiments et des parafoudres sur les alimentations des matériels sensibles.','Faire réaliser une étude foudre des sites sensibles.','Prévoir des vérifications régulières des protections.']),
  ('REG 15-1', 'Aucune restriction n''encadre la maintenance : n''importe quel agent ou prestataire peut intervenir sur les équipements sans autorisation préalable.', ARRAY['Altération ou sabotage de matériels par des intervenants non qualifiés.','Installation de logiciels ou accès frauduleux lors d''une intervention.','Pannes causées par des manipulations non maîtrisées.'], ARRAY['Réserver immédiatement la maintenance au personnel nommément autorisé.','Exiger une autorisation écrite avant chaque intervention.','Contrôler l''identité des intervenants externes à l''entrée.']),
  ('REG 15-2', 'Aucun contrat de maintenance n''est établi avec des fournisseurs accrédités pour les matériels en service.', ARRAY['Absence de support lors de pannes d''équipements critiques.','Interventions par des prestataires non accrédités et non encadrés.','Indisponibilité prolongée faute de pièces et d''engagement du fournisseur.'], ARRAY['Établir sans délai des contrats avec des fournisseurs accrédités pour tous les matériels critiques.','Recenser les matériels en service sans couverture de maintenance.','Intégrer la contractualisation au processus de mise en service.']),
  ('REG 15-3', 'Les contrats de maintenance ne comportent aucune clause de qualité de service, de disponibilité, de temps de réponse ou de rechange et n''ont pas été approuvés par le responsable de l''entité.', ARRAY['Aucun recours contractuel en cas de retard ou de mauvaise prestation du fournisseur.','Indisponibilité prolongée des services critiques sans pénalité.','Engagements financiers non validés par la direction.'], ARRAY['Renégocier les contrats avec des clauses de niveau de service, disponibilité, délais et rechange.','Soumettre chaque contrat à l''approbation du responsable de l''entité.','Définir un modèle de contrat type.']),
  ('REG 15-4', 'Aucun registre de maintenance n''est ouvert : les interventions, paiements et échéances de contrat ne sont pas tracés.', ARRAY['Aucune traçabilité des interventions réalisées sur les équipements.','Paiements injustifiés ou doublons non détectés.','Perte du suivi de performance et d''expiration des contrats.'], ARRAY['Ouvrir sans délai un registre de maintenance par unité de maintenance.','Y consigner chaque intervention, paiement, évaluation de qualité et échéance.','Désigner un responsable de sa tenue.']),
  ('REG 15-5', 'Aucune approbation du travail des fournisseurs n''est exigée des administrateurs systèmes, réseaux et bases de données, et aucun registre n''est tenu.', ARRAY['Modifications non contrôlées des systèmes par des prestataires.','Anomalies introduites lors de la maintenance non détectées.','Aucune imputabilité en cas d''incident après intervention.'], ARRAY['Imposer l''approbation écrite de chaque intervention par l''administrateur responsable.','Ouvrir un registre des travaux approuvés.','Refuser le paiement des prestations non validées.']),
  ('REG 15-6', 'Les prestataires interviennent sur les systèmes sans surveillance des ASSI, avec un accès libre aux fichiers et sans contrôle contre la copie de données.', ARRAY['Exfiltration de données sensibles par un prestataire.','Installation de code malveillant ou porte dérobée lors d''une maintenance.','Modification non tracée de configurations critiques.'], ARRAY['Interdire toute intervention de prestataire sans la présence d''un ASSI.','Contrôler les supports et accès pour empêcher toute copie de fichiers ou programmes.','Journaliser les interventions et les accès accordés.']),
  ('REG 15-7', 'Aucun dossier de maintenance n''est conservé : les rapports et justificatifs d''intervention ne sont pas archivés.', ARRAY['Aucun suivi de l''historique des interventions sur les équipements.','Impossibilité de justifier les prestations ou de faire valoir une garantie.','Récurrence de pannes non analysées.'], ARRAY['Mettre en place l''archivage systématique des dossiers de maintenance.','Exiger un rapport écrit de chaque intervention du fournisseur.','Désigner un responsable de leur conservation.']),
  ('REG 15-8', 'Les équipements sont remis en réparation avec leurs données, sans sauvegarde préalable sur d''autres supports ni suppression sécurisée.', ARRAY['Fuite de données sensibles ou classifiées vers le réparateur.','Perte définitive de données en cas de panne ou de remplacement du support.','Réutilisation du matériel réparé avec des données d''origine accessibles.'], ARRAY['Interdire toute remise en réparation sans sauvegarde et suppression sécurisée préalables.','Définir une procédure d''effacement conforme aux données hébergées.','Imposer une clause de confidentialité au réparateur.']),
  ('REG 16-1', 'Les supports amovibles de données sensibles (disques, clés USB, bandes, DVD) sont laissés sans protection, sans coffre ni armoire.', ARRAY['Vol de données sensibles ou classifiées par simple prélèvement d''un support.','Divulgation d''informations confidentielles de l''entité.','Perte de supports sans que le vol ne soit détecté.'], ARRAY['Fournir sans délai des coffres ou armoires sécurisés et y ranger tous les supports sensibles.','Établir un inventaire et une procédure de sortie des supports.','Chiffrer les supports contenant des données sensibles.']),
  ('REG 16-2', 'Les clés des locaux, coffres et armoires restent en libre accès (laissées sur les serrures ou sur les bureaux) après les heures de travail.', ARRAY['Accès nocturne libre aux locaux, coffres et armoires contenant des informations sensibles.','Vol de documents ou supports sans effraction apparente.','Aucune imputabilité en cas de disparition.'], ARRAY['Retirer immédiatement les clés des serrures et les placer dans un endroit sûr à accès restreint.','Désigner les personnes autorisées à détenir les clés.','Mettre en place un registre et des doubles sécurisés.']),
  ('REG 16-3', 'Les fichiers classifiés périmés ne sont jamais effacés ou ne le sont que par simple suppression logique, sans aucun effacement physique.', ARRAY['Accumulation d''informations classifiées obsolètes exposées à la fuite.','Récupération aisée de données supprimées sur des supports réaffectés ou jetés.','Divulgation d''informations sensibles à des tiers.'], ARRAY['Mettre en œuvre sans délai l''effacement logique et physique des fichiers classifiés périmés.','Définir les durées de conservation par classification.','Utiliser des outils d''effacement sécurisé ou détruire les supports.']),
  ('REG 16-4', 'Les documents sensibles ou classifiés sont laissés sans surveillance dans les imprimantes, photocopieuses, scanneurs et télécopieurs, sans pratique de retrait immédiat.', ARRAY['Fuite d''informations classifiées par simple lecture ou prélèvement.','Utilisation malveillante de documents sensibles en libre accès.','Perte de confidentialité fréquente et non détectée.'], ARRAY['Imposer le retrait immédiat des documents sensibles après impression ou copie.','Placer les appareils dans des zones à accès contrôlé.','Activer l''impression sécurisée pour les documents sensibles.']),
  ('REG 16-5', 'Aucun verrouillage automatique n''est configuré : ordinateurs et terminaux restent connectés et accessibles en l''absence de leurs utilisateurs.', ARRAY['Accès libre aux données et applications par toute personne passant devant un poste ouvert.','Usurpation d''identité et actions frauduleuses impossibles à imputer.','Fuite d''informations sensibles affichées à l''écran.'], ARRAY['Déployer par stratégie centralisée un verrouillage automatique à délai court sur tous les postes.','Exiger une authentification pour déverrouiller.','Imposer la déconnexion en fin de journée.']),
  ('REG 16-6', 'Aucune interdiction ni contrôle n''encadre l''usage des photocopieurs, scanneurs et appareils photo : toute personne peut reproduire librement des documents.', ARRAY['Reproduction massive de documents classifiés sans traçabilité.','Exfiltration d''informations par photographie ou numérisation.','Divulgation d''informations sensibles à des tiers.'], ARRAY['Interdire formellement toute reproduction non autorisée et diffuser la règle.','Restreindre l''accès aux appareils par code ou badge avec journalisation.','Interdire les appareils photo dans les zones sensibles.']),
  ('REG 16-7', 'Aucune imprimante n''est dotée d''une identification par code personnel : les documents s''impriment immédiatement et sont récupérables par tout le monde.', ARRAY['Consultation ou vol de documents sensibles dans les bacs de sortie.','Impossibilité de savoir qui a imprimé ou récupéré un document.','Fuite d''informations classifiées via les imprimantes partagées.'], ARRAY['Acquérir ou configurer des imprimantes avec libération par code personnel.','Imposer l''impression sécurisée à tous les utilisateurs.','Placer les imprimantes partagées dans des zones contrôlées.']),
  ('REG 17-1', 'Aucune mesure de sécurité n''est spécifiée pour les applications métier : leur sécurisation dépend des choix individuels des équipes projet.', ARRAY['Applications traitant des données sensibles exposées sans contrôle d''accès ni traçabilité adaptés.','Compromission d''applications critiques sans possibilité de détection ni d''imputation.','Non-respect d''une exigence majeure de la PSSI-ES.'], ARRAY['Rédiger en urgence les exigences de sécurité applicatives minimales pour toutes les applications métier.','Prioriser l''évaluation des applications traitant des données classifiées.','Rendre ces exigences obligatoires dans les cahiers des charges et recettes.']),
  ('REG 17-2', 'Des accès aux informations sensibles sont accordés du seul fait du grade ou de la fonction, sans habilitation ni vérification du besoin d''en connaître.', ARRAY['Fuite massive d''informations sensibles à l''initiative de personnels non habilités.','Impossibilité de justifier les accès lors d''un incident ou d''un contrôle.','Non-respect d''une exigence majeure de la PSSI-ES.'], ARRAY['Suspendre les accès non justifiés aux informations sensibles et les rétablir sur validation du propriétaire.','Mettre en place un processus d''habilitation formalisé et tracé.','Auditer sans délai les droits sur les ressources classifiées.']),
  ('REG 17-3', 'L''accès aux moyens de traitement des informations sensibles est accordé du seul fait du grade ou du titre, sans habilitation ni besoin d''utiliser démontré.', ARRAY['Manipulation ou altération de systèmes sensibles par des personnes non habilitées.','Compromission d''équipements critiques via des comptes sans justification.','Non-respect d''une exigence majeure de la PSSI-ES.'], ARRAY['Retirer immédiatement les accès aux moyens de traitement sensibles sans habilitation ni besoin avéré.','Instaurer une procédure d''autorisation formelle par ressource.','Journaliser et contrôler les accès à ces moyens.']),
  ('REG 17-4', 'Aucun cloisonnement des rôles n''est mis en œuvre : les mêmes comptes administrent, exploitent et valident sans séparation des tâches.', ARRAY['Fraude ou sabotage possibles par un seul individu sans détection.','Absence de contrôle indépendant sur les actions d''administration.','Non-respect d''une exigence majeure de la PSSI-ES.'], ARRAY['Définir sans délai une matrice des rôles avec séparation des tâches.','Créer des comptes distincts pour administration et usage courant.','Revoir en priorité les comptes cumulant les privilèges les plus élevés.']),
  ('REG 17-5', 'Aucune revue des droits d''accès n''est réalisée : des comptes d''agents partis ou mutés restent actifs avec leurs privilèges d''origine.', ARRAY['Utilisation de comptes orphelins pour des accès frauduleux.','Privilèges excessifs généralisés et non maîtrisés.','Non-respect d''une exigence majeure de la PSSI-ES.'], ARRAY['Lancer immédiatement un recensement et la désactivation des comptes orphelins.','Mettre en place une revue au moins annuelle des droits, formalisée.','Connecter la gestion des comptes au processus RH de départ et mutation.']),
  ('REG 17-6', 'Aucune revue des privilèges n''est effectuée lors des changements de poste : les agents mutés conservent l''intégralité de leurs anciens droits.', ARRAY['Accumulation de privilèges permettant des accès critiques non justifiés.','Contournement de la séparation des tâches par cumul de fonctions.','Non-respect d''une exigence majeure de la PSSI-ES.'], ARRAY['Auditer en urgence les droits des agents mutés ces 12 derniers mois.','Rendre la revue des droits obligatoire dans la procédure de mutation.','Automatiser l''alerte RH vers l''administrateur des accès.'])
) as t(code, descr, risks, recos)
join public.controls c on c.code = t.code
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000017')
where not exists (
  select 1 from public.finding_templates ft
  where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'major_nc'
);
